window.TXB=window.TXB||{};TXB["svd/Luk"]={"11:54":"وهم يراقبونه طالبين أن يصطادوا شيئا من فمه لكي يشتكوا عليه.","12:1":"وفي أثناء ذلك, إذ اجتمع ربوات الشعب, حتى كان بعضهم يدوس بعضا, ابتدأ يقول لتلاميذه: «أولا تحرزوا لأنفسكم من خمير الفريسيين الذي هو الرياء","12:2":"فليس مكتوم لن يستعلن, ولا خفي لن يعرف.","12:3":"لذلك كل ما قلتموه في الظلمة يسمع في النور, وما كلمتم به الأذن في المخادع ينادى به على السطوح.","12:4":"ولكن أقول لكم يا أحبائي: لا تخافوا من الذين يقتلون الجسد, وبعد ذلك ليس لهم ما يفعلون أكثر.","12:5":"بل أريكم ممن تخافون: خافوا من الذي بعدما يقتل, له سلطان أن يلقي في جهنم. نعم, أقول لكم: من هذا خافوا!","12:6":"أليست خمسة عصافير تباع بفلسين, وواحد منها ليس منسيا أمام الله؟","12:7":"بل شعور رؤوسكم أيضا جميعها محصاة! فلا تخافوا. أنتم أفضل من عصافير كثيرة!","12:8":"وأقول لكم: كل من اعترف بي قدام الناس, يعترف به ابن الإنسان قدام ملائكة الله.","12:9":"ومن أنكرني قدام الناس, ينكر قدام ملائكة الله.","12:10":"وكل من قال كلمة على ابن الإنسان يغفر له, وأما من جدف على الروح القدس فلا يغفر له.","12:11":"ومتى قدموكم إلى المجامع والرؤساء والسلاطين فلا تهتموا كيف أو بما تحتجون أو بما تقولون","12:12":"لأن الروح القدس يعلمكم في تلك الساعة ما يجب أن تقولوه».","12:13":"وقال له واحد من الجمع: «يا معلم, قل لأخي أن يقاسمني الميراث».","12:14":"فقال له: «يا إنسان من أقامني عليكما قاضيا أو مقسما؟»","12:15":"وقال لهم: «انظروا وتحفظوا من الطمع, فإنه متى كان لأحد كثير فليست حياته من أمواله».","12:16":"وضرب لهم مثلا قائلا: «إنسان غني أخصبت كورته","12:17":"ففكر في نفسه قائلا: ماذا أعمل, لأن ليس لي موضع أجمع فيه أثماري؟","12:18":"وقال: أعمل هذا: أهدم مخازني وأبني أعظم, وأجمع هناك جميع غلاتي وخيراتي","12:19":"وأقول لنفسي: يا نفس لك خيرات كثيرة, موضوعة لسنين كثيرة. استريحي وكلي واشربي وافرحي.","12:20":"فقال له الله: يا غبي هذه الليلة تطلب نفسك منك فهذه التي أعددتها لمن تكون؟","12:21":"هكذا الذي يكنز لنفسه وليس هو غنيا لله».","12:22":"وقال لتلاميذه: «من أجل هذا أقول لكم: لا تهتموا لحياتكم بما تأكلون, ولا للجسد بما تلبسون.","12:23":"الحياة أفضل من الطعام, والجسد أفضل من اللباس.","12:24":"تأملوا الغربان: أنها لا تزرع ولا تحصد, وليس لها مخدع ولا مخزن, والله يقيتها. كم أنتم بالحري أفضل من الطيور!","12:25":"ومن منكم إذا اهتم يقدر أن يزيد على قامته ذراعا واحدة؟","12:26":"فإن كنتم لا تقدرون ولا على الأصغر, فلماذا تهتمون بالبواقي؟","12:27":"تأملوا الزنابق كيف تنمو! لا تتعب ولا تغزل, ولكن أقول لكم إنه ولا سليمان في كل مجده كان يلبس كواحدة منها.","12:28":"فإن كان العشب الذي يوجد اليوم في الحقل ويطرح غدا في التنور يلبسه الله هكذا, فكم بالحري يلبسكم أنتم يا قليلي الإيمان؟","12:29":"فلا تطلبوا أنتم ما تأكلون وما تشربون ولا تقلقوا","12:30":"فإن هذه كلها تطلبها أمم العالم. وأما أنتم فأبوكم يعلم أنكم تحتاجون إلى هذه.","12:31":"بل اطلبوا ملكوت الله, وهذه كلها تزاد لكم.","12:32":"«لا تخف, أيها القطيع الصغير, لأن أباكم قد سر أن يعطيكم الملكوت.","12:33":"بيعوا ما لكم وأعطوا صدقة. اعملوا لكم أكياسا لا تفنى وكنزا لا ينفد في السماوات, حيث لا يقرب سارق ولا يبلي سوس","12:34":"لأنه حيث يكون كنزكم هناك يكون قلبكم أيضا.","12:35":"لتكن أحقاؤكم ممنطقة وسرجكم موقدة","12:36":"وأنتم مثل أناس ينتظرون سيدهم متى يرجع من العرس, حتى إذا جاء وقرع يفتحون له للوقت.","12:37":"طوبى لأولئك العبيد الذين إذا جاء سيدهم يجدهم ساهرين. الحق أقول لكم إنه يتمنطق ويتكئهم ويتقدم ويخدمهم.","12:38":"وإن أتى في الهزيع الثاني أو أتى في الهزيع الثالث ووجدهم هكذا, فطوبى لأولئك العبيد.","12:39":"وإنما اعلموا هذا: أنه لو عرف رب البيت في أية ساعة يأتي السارق لسهر, ولم يدع بيته ينقب.","12:40":"فكونوا أنتم إذا مستعدين, لأنه في ساعة لا تظنون يأتي ابن الإنسان».","12:41":"فقال له بطرس: «يا رب ألنا تقول هذا المثل أم للجميع أيضا؟»","12:42":"فقال الرب: «فمن هو الوكيل الأمين الحكيم الذي يقيمه سيده على خدمه ليعطيهم العلوفة في حينها؟","12:43":"طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا!","12:44":"بالحق أقول لكم إنه يقيمه على جميع أمواله.","12:45":"ولكن إن قال ذلك العبد في قلبه: سيدي يبطئ قدومه, فيبتدئ يضرب الغلمان والجواري, ويأكل ويشرب ويسكر.","12:46":"يأتي سيد ذلك العبد في يوم لا ينتظره وفي ساعة لا يعرفها, فيقطعه ويجعل نصيبه مع الخائنين.","12:47":"وأما ذلك العبد الذي يعلم إرادة سيده ولا يستعد ولا يفعل بحسب إرادته, فيضرب كثيرا.","12:48":"ولكن الذي لا يعلم, ويفعل ما يستحق ضربات, يضرب قليلا. فكل من أعطي كثيرا يطلب منه كثير, ومن يودعونه كثيرا يطالبونه بأكثر.","12:49":"«جئت لألقي نارا على الأرض, فماذا أريد لو اضطرمت؟","12:50":"ولي صبغة أصطبغها, وكيف أنحصر حتى تكمل؟","12:51":"أتظنون أني جئت لأعطي سلاما على الأرض؟ كلا, أقول لكم! بل انقساما.","12:52":"لأنه يكون من الآن خمسة في بيت واحد منقسمين: ثلاثة على اثنين, واثنان على ثلاثة.","12:53":"ينقسم الأب على الابن, والابن على الأب, والأم على البنت, والبنت على الأم, والحماة على كنتها, والكنة على حماتها».","12:54":"ثم قال أيضا للجموع: «إذا رأيتم السحاب تطلع من المغارب فللوقت تقولون: إنه يأتي مطر. فيكون هكذا.","12:55":"وإذا رأيتم ريح الجنوب تهب تقولون: إنه سيكون حر. فيكون.","12:56":"يا مراؤون تعرفون أن تميزوا وجه الأرض والسماء وأما هذا الزمان فكيف لا تميزونه؟","12:57":"ولماذا لا تحكمون بالحق من قبل نفوسكم؟","12:58":"حينما تذهب مع خصمك إلى الحاكم, ابذل الجهد وأنت في الطريق لتتخلص منه, لئلا يجرك إلى القاضي, ويسلمك القاضي إلى الحاكم, فيلقيك الحاكم في السجن.","12:59":"أقول لك: لا تخرج من هناك حتى توفي الفلس الأخير».","13:1":"وكان حاضرا في ذلك الوقت قوم يخبرونه عن الجليليين الذين خلط بيلاطس دمهم بذبائحهم.","13:2":"فأجاب يسوع وقال لهم: «أتظنون أن هؤلاء الجليليين كانوا خطاة أكثر من كل الجليليين لأنهم كابدوا مثل هذا؟","13:3":"كلا أقول لكم. بل إن لم تتوبوا فجميعكم كذلك تهلكون.","13:4":"أو أولئك الثمانية عشر الذين سقط عليهم البرج في سلوام وقتلهم, أتظنون أن هؤلاء كانوا مذنبين أكثر من جميع الناس الساكنين في أورشليم؟","13:5":"كلا أقول لكم! بل إن لم تتوبوا فجميعكم كذلك تهلكون».","13:6":"وقال هذا المثل: «كانت لواحد شجرة تين مغروسة في كرمه, فأتى يطلب فيها ثمرا ولم يجد.","13:7":"فقال للكرام: هوذا ثلاث سنين آتي أطلب ثمرا في هذه التينة ولم أجد. اقطعها. لماذا تبطل الأرض أيضا؟","13:8":"فأجاب وقال له: يا سيد, اتركها هذه السنة أيضا, حتى أنقب حولها وأضع زبلا.","13:9":"فإن صنعت ثمرا, وإلا ففيما بعد تقطعها».","13:10":"وكان يعلم في أحد المجامع في السبت","13:11":"وإذا امرأة كان بها روح ضعف ثماني عشرة سنة, وكانت منحنية ولم تقدر أن تنتصب البتة.","13:12":"فلما رآها يسوع دعاها وقال لها: «يا امرأة, إنك محلولة من ضعفك».","13:13":"ووضع عليها يديه, ففي الحال استقامت ومجدت الله.","13:14":"فأجاب رئيس المجمع, وهو مغتاظ لأن يسوع أبرأ في السبت, وقال للجمع: «هي ستة أيام ينبغي فيها العمل, ففي هذه ائتوا واستشفوا, وليس في يوم السبت»","13:15":"فأجابه الرب وقال: «يا مرائي ألا يحل كل واحد منكم في السبت ثوره أو حماره من المذود ويمضي به ويسقيه؟","13:16":"وهذه, وهي ابنة إبراهيم, قد ربطها الشيطان ثماني عشرة سنة, أما كان ينبغي أن تحل من هذا الرباط في يوم السبت؟»","13:17":"وإذ قال هذا أخجل جميع الذين كانوا يعاندونه, وفرح كل الجمع بجميع الأعمال المجيدة الكائنة منه.","13:18":"فقال: «ماذا يشبه ملكوت الله وبماذا أشبهه؟","13:19":"يشبه حبة خردل أخذها إنسان وألقاها في بستانه, فنمت وصارت شجرة كبيرة, وتآوت طيور السماء في أغصانها».","13:20":"وقال أيضا: «بماذا أشبه ملكوت الله؟","13:21":"يشبه خميرة أخذتها امرأة وخبأتها في ثلاثة أكيال دقيق حتى اختمر الجميع».","13:22":"واجتاز في مدن وقرى يعلم ويسافر نحو أورشليم","13:23":"فقال له واحد: «يا سيد, أقليل هم الذين يخلصون؟» فقال لهم:","13:24":"«اجتهدوا أن تدخلوا من الباب الضيق, فإني أقول لكم: إن كثيرين سيطلبون أن يدخلوا ولا يقدرون","13:25":"من بعد ما يكون رب البيت قد قام وأغلق الباب وابتدأتم تقفون خارجا وتقرعون الباب قائلين: يا رب يا رب افتح لنا يجيب ويقول لكم: لا أعرفكم من أين أنتم!","13:26":"حينئذ تبتدئون تقولون: أكلنا قدامك وشربنا, وعلمت في شوارعنا.","13:27":"فيقول: أقول لكم لا أعرفكم من أين أنتم! تباعدوا عني يا جميع فاعلي الظلم.","13:28":"هناك يكون البكاء وصرير الأسنان, متى رأيتم إبراهيم وإسحاق ويعقوب وجميع الأنبياء في ملكوت الله, وأنتم مطروحون خارجا.","13:29":"ويأتون من المشارق ومن المغارب ومن الشمال والجنوب, ويتكئون في ملكوت الله.","13:30":"وهوذا آخرون يكونون أولين, وأولون يكونون آخرين».","13:31":"في ذلك اليوم تقدم بعض الفريسيين قائلين له: «اخرج واذهب من ههنا, لأن هيرودس يريد أن يقتلك».","13:32":"فقال لهم: «امضوا وقولوا لهذا الثعلب: ها أنا أخرج شياطين, وأشفي اليوم وغدا, وفي اليوم الثالث أكمل.","13:33":"بل ينبغي أن أسير اليوم وغدا وما يليه, لأنه لا يمكن أن يهلك نبي خارجا عن أورشليم.","13:34":"يا أورشليم, يا أورشليم يا قاتلة الأنبياء وراجمة المرسلين إليها, كم مرة أردت أن أجمع أولادك كما تجمع الدجاجة فراخها تحت جناحيها, ولم تريدوا.","13:35":"هوذا بيتكم يترك لكم خرابا! والحق أقول لكم: إنكم لا ترونني حتى يأتي وقت تقولون فيه: مبارك الآتي باسم الرب».","14:1":"وإذ جاء إلى بيت أحد رؤساء الفريسيين في السبت ليأكل خبزا, كانوا يراقبونه.","14:2":"وإذا إنسان مستسق كان قدامه.","14:3":"فأجاب يسوع وكلم الناموسيين والفريسيين قائلا: «هل يحل الإبراء في السبت؟»","14:4":"فسكتوا. فأمسكه وأبرأه وأطلقه.","14:5":"ثم أجابهم وقال: «من منكم يسقط حماره أو ثوره في بئر ولا ينشله حالا في يوم السبت؟»","14:6":"فلم يقدروا أن يجيبوه عن ذلك.","14:7":"وقال للمدعوين مثلا, وهو يلاحظ كيف اختاروا المتكآت الأولى قائلا لهم:","14:8":"«متى دعيت من أحد إلى عرس فلا تتكئ في المتكإ الأول, لعل أكرم منك يكون قد دعي منه.","14:9":"فيأتي الذي دعاك وإياه ويقول لك: أعط مكانا لهذا. فحينئذ تبتدئ بخجل تأخذ الموضع الأخير.","14:10":"بل متى دعيت فاذهب واتكئ في الموضع الأخير, حتى إذا جاء الذي دعاك يقول لك: يا صديق, ارتفع إلى فوق. حينئذ يكون لك مجد أمام المتكئين معك.","14:11":"لأن كل من يرفع نفسه يتضع ومن يضع نفسه يرتفع».","14:12":"وقال أيضا للذي دعاه: «إذا صنعت غداء أو عشاء فلا تدع أصدقاءك ولا إخوتك ولا أقرباءك ولا الجيران الأغنياء, لئلا يدعوك هم أيضا, فتكون لك مكافاة.","14:13":"بل إذا صنعت ضيافة فادع المساكين: الجدع, العرج, العمي","14:14":"فيكون لك الطوبى إذ ليس لهم حتى يكافوك, لأنك تكافى في قيامة الأبرار».","14:15":"فلما سمع ذلك واحد من المتكئين قال له: «طوبى لمن يأكل خبزا في ملكوت الله».","14:16":"فقال له: «إنسان صنع عشاء عظيما ودعا كثيرين","14:17":"وأرسل عبده في ساعة العشاء ليقول للمدعوين: تعالوا لأن كل شيء قد أعد.","14:18":"فابتدأ الجميع برأي واحد يستعفون. قال له الأول: إني اشتريت حقلا, وأنا مضطر أن أخرج وأنظره. أسألك أن تعفيني.","14:19":"وقال آخر: إني اشتريت خمسة أزواج بقر, وأنا ماض لأمتحنها. أسألك أن تعفيني.","14:20":"وقال آخر: إني تزوجت بامرأة, فلذلك لا أقدر أن أجيء.","14:21":"فأتى ذلك العبد وأخبر سيده بذلك. حينئذ غضب رب البيت, وقال لعبده: اخرج عاجلا إلى شوارع المدينة وأزقتها, وأدخل إلى هنا المساكين والجدع والعرج والعمي.","14:22":"فقال العبد: يا سيد, قد صار كما أمرت, ويوجد أيضا مكان.","14:23":"فقال السيد للعبد: اخرج إلى الطرق والسياجات وألزمهم بالدخول حتى يمتلئ بيتي","14:24":"لأني أقول لكم إنه ليس واحد من أولئك الرجال المدعوين يذوق عشائي».","14:25":"وكان جموع كثيرة سائرين معه, فالتفت وقال لهم:","14:26":"«إن كان أحد يأتي إلي ولا يبغض أباه وأمه وامرأته وأولاده وإخوته وأخواته, حتى نفسه أيضا, فلا يقدر أن يكون لي تلميذا.","14:27":"ومن لا يحمل صليبه ويأتي ورائي فلا يقدر أن يكون لي تلميذا.","14:28":"ومن منكم وهو يريد أن يبني برجا لا يجلس أولا ويحسب النفقة, هل عنده ما يلزم لكماله؟","1:1":"إذ كان كثيرون قد أخذوا بتأليف قصة في الأمور المتيقنة عندنا","1:2":"كما سلمها إلينا الذين كانوا منذ البدء معاينين وخداما للكلمة","1:3":"رأيت أنا أيضا إذ قد تتبعت كل شيء من الأول بتدقيق, أن أكتب على التوالي إليك أيها العزيز ثاوفيلس","1:4":"لتعرف صحة الكلام الذي علمت به.","1:5":"كان في أيام هيرودس ملك اليهودية كاهن اسمه زكريا من فرقة أبيا, وامرأته من بنات هارون واسمها أليصابات.","1:6":"وكانا كلاهما بارين أمام الله, سالكين في جميع وصايا الرب وأحكامه بلا لوم.","1:7":"ولم يكن لهما ولد, إذ كانت أليصابات عاقرا. وكانا كلاهما متقدمين في أيامهما.","1:8":"فبينما هو يكهن في نوبة فرقته أمام الله","1:9":"حسب عادة الكهنوت, أصابته القرعة أن يدخل إلى هيكل الرب ويبخر.","1:10":"وكان كل جمهور الشعب يصلون خارجا وقت البخور.","1:11":"فظهر له ملاك الرب واقفا عن يمين مذبح البخور.","1:12":"فلما رآه زكريا اضطرب ووقع عليه خوف.","1:13":"فقال له الملاك: «لا تخف يا زكريا, لأن طلبتك قد سمعت, وامرأتك أليصابات ستلد لك ابنا وتسميه يوحنا.","1:14":"ويكون لك فرح وابتهاج, وكثيرون سيفرحون بولادته","1:15":"لأنه يكون عظيما أمام الرب, وخمرا ومسكرا لا يشرب, ومن بطن أمه يمتلئ من الروح القدس.","1:16":"ويرد كثيرين من بني إسرائيل إلى الرب إلههم.","1:17":"ويتقدم أمامه بروح إيليا وقوته, ليرد قلوب الآباء إلى الأبناء, والعصاة إلى فكر الأبرار, لكي يهيئ للرب شعبا مستعدا».","1:18":"فقال زكريا للملاك: «كيف أعلم هذا, لأني أنا شيخ وامرأتي متقدمة في أيامها؟»","1:19":"فأجاب الملاك وقال له: «أنا جبرائيل الواقف قدام الله, وأرسلت لأكلمك وأبشرك بهذا.","1:20":"وها أنت تكون صامتا ولا تقدر أن تتكلم, إلى اليوم الذي يكون فيه هذا, لأنك لم تصدق كلامي الذي سيتم في وقته».","1:21":"وكان الشعب منتظرين زكريا ومتعجبين من إبطائه في الهيكل.","1:22":"فلما خرج لم يستطع أن يكلمهم, ففهموا أنه قد رأى رؤيا في الهيكل. فكان يومئ إليهم وبقي صامتا.","1:23":"ولما كملت أيام خدمته مضى إلى بيته.","1:24":"وبعد تلك الأيام حبلت أليصابات امرأته, وأخفت نفسها خمسة أشهر قائلة:","1:25":"«هكذا قد فعل بي الرب في الأيام التي فيها نظر إلي, لينزع عاري بين الناس».","1:26":"وفي الشهر السادس أرسل جبرائيل الملاك من الله إلى مدينة من الجليل اسمها ناصرة","1:27":"إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف. واسم العذراء مريم.","1:28":"فدخل إليها الملاك وقال: «سلام لك أيتها المنعم عليها! الرب معك. مباركة أنت في النساء».","1:29":"فلما رأته اضطربت من كلامه, وفكرت ما عسى أن تكون هذه التحية!","1:30":"فقال لها الملاك: «لا تخافي يا مريم, لأنك قد وجدت نعمة عند الله.","1:31":"وها أنت ستحبلين وتلدين ابنا وتسمينه يسوع.","1:32":"هذا يكون عظيما, وابن العلي يدعى, ويعطيه الرب الإله كرسي داود أبيه","1:33":"ويملك على بيت يعقوب إلى الأبد, ولا يكون لملكه نهاية».","1:34":"فقالت مريم للملاك: «كيف يكون هذا وأنا لست أعرف رجلا؟»","1:35":"فأجاب الملاك وقال لها: «الروح القدس يحل عليك, وقوة العلي تظللك, فلذلك أيضا القدوس المولود منك يدعى ابن الله.","1:36":"وهوذا أليصابات نسيبتك هي أيضا حبلى بابن في شيخوختها, وهذا هو الشهر السادس لتلك المدعوة عاقرا","1:37":"لأنه ليس شيء غير ممكن لدى الله».","1:38":"فقالت مريم: «هوذا أنا أمة الرب. ليكن لي كقولك». فمضى من عندها الملاك.","1:39":"فقامت مريم في تلك الأيام وذهبت بسرعة إلى الجبال إلى مدينة يهوذا","1:40":"ودخلت بيت زكريا وسلمت على أليصابات.","1:41":"فلما سمعت أليصابات سلام مريم ارتكض الجنين في بطنها, وامتلأت أليصابات من الروح القدس","1:42":"وصرخت بصوت عظيم وقالت: «مباركة أنت في النساء ومباركة هي ثمرة بطنك!","1:43":"فمن أين لي هذا أن تأتي أم ربي إلي؟","1:44":"فهوذا حين صار صوت سلامك في أذني ارتكض الجنين بابتهاج في بطني.","1:45":"فطوبى للتي آمنت أن يتم ما قيل لها من قبل الرب».","1:46":"فقالت مريم: «تعظم نفسي الرب","1:47":"وتبتهج روحي بالله مخلصي","1:48":"لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني","1:49":"لأن القدير صنع بي عظائم, واسمه قدوس","1:50":"ورحمته إلى جيل الأجيال للذين يتقونه.","1:51":"صنع قوة بذراعه. شتت المستكبرين بفكر قلوبهم.","1:52":"أنزل الأعزاء عن الكراسي ورفع المتضعين.","1:53":"أشبع الجياع خيرات وصرف الأغنياء فارغين.","1:54":"عضد إسرائيل فتاه ليذكر رحمة","1:55":"كما كلم آباءنا. لإبراهيم ونسله إلى الأبد».","1:56":"فمكثت مريم عندها نحو ثلاثة أشهر, ثم رجعت إلى بيتها.","1:57":"وأما أليصابات فتم زمانها لتلد, فولدت ابنا.","1:58":"وسمع جيرانها وأقرباؤها أن الرب عظم رحمته لها, ففرحوا معها.","1:59":"وفي اليوم الثامن جاءوا ليختنوا الصبي, وسموه باسم أبيه زكريا.","1:60":"فأجابت أمه وقالت: «لا بل يسمى يوحنا».","1:61":"فقالوا لها: «ليس أحد في عشيرتك تسمى بهذا الاسم».","1:62":"ثم أومأوا إلى أبيه, ماذا يريد أن يسمى.","1:63":"فطلب لوحا وكتب قائلا: «اسمه يوحنا». فتعجب الجميع.","1:64":"وفي الحال انفتح فمه ولسانه وتكلم وبارك الله.","1:65":"فوقع خوف على كل جيرانهم. وتحدث بهذه الأمور جميعها في كل جبال اليهودية","1:66":"فأودعها جميع السامعين في قلوبهم قائلين: «أترى ماذا يكون هذا الصبي؟» وكانت يد الرب معه.","1:67":"وامتلأ زكريا أبوه من الروح القدس, وتنبأ قائلا:","1:68":"«مبارك الرب إله إسرائيل لأنه افتقد وصنع فداء لشعبه","1:69":"وأقام لنا قرن خلاص في بيت داود فتاه.","1:70":"كما تكلم بفم أنبيائه القديسين الذين هم منذ الدهر.","1:71":"خلاص من أعدائنا ومن أيدي جميع مبغضينا.","1:72":"ليصنع رحمة مع آبائنا ويذكر عهده المقدس.","1:73":"القسم الذي حلف لإبراهيم أبينا:","1:74":"أن يعطينا إننا بلا خوف, منقذين من أيدي أعدائنا, نعبده","1:75":"بقداسة وبر قدامه جميع أيام حياتنا.","1:76":"وأنت أيها الصبي نبي العلي تدعى, لأنك تتقدم أمام وجه الرب لتعد طرقه.","1:77":"لتعطي شعبه معرفة الخلاص بمغفرة خطاياهم","1:78":"بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء.","1:79":"ليضيء على الجالسين في الظلمة وظلال الموت, لكي يهدي أقدامنا في طريق السلام».","1:80":"أما الصبي فكان ينمو ويتقوى بالروح, وكان في البراري إلى يوم ظهوره لإسرائيل.","2:1":"وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة.","2:2":"وهذا الاكتتاب الأول جرى إذ كان كيرينيوس والي سورية.","2:3":"فذهب الجميع ليكتتبوا, كل واحد إلى مدينته.","2:4":"فصعد يوسف أيضا من الجليل من مدينة الناصرة إلى اليهودية, إلى مدينة داود التي تدعى بيت لحم, لكونه من بيت داود وعشيرته","2:5":"ليكتتب مع مريم امرأته المخطوبة وهي حبلى.","2:6":"وبينما هما هناك تمت أيامها لتلد.","2:7":"فولدت ابنها البكر وقمطته وأضجعته في المذود, إذ لم يكن لهما موضع في المنزل.","2:8":"وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل على رعيتهم","2:9":"وإذا ملاك الرب وقف بهم, ومجد الرب أضاء حولهم, فخافوا خوفا عظيما.","2:10":"فقال لهم الملاك: «لا تخافوا. فها أنا أبشركم بفرح عظيم يكون لجميع الشعب:","2:11":"أنه ولد لكم اليوم في مدينة داود مخلص هو المسيح الرب.","2:12":"وهذه لكم العلامة: تجدون طفلا مقمطا مضجعا في مذود».","2:13":"وظهر بغتة مع الملاك جمهور من الجند السماوي مسبحين الله وقائلين:","2:14":"«المجد لله في الأعالي, وعلى الأرض السلام, وبالناس المسرة».","2:15":"ولما مضت عنهم الملائكة إلى السماء, قال الرجال الرعاة بعضهم لبعض: «لنذهب الآن إلى بيت لحم وننظر هذا الأمر الواقع الذي أعلمنا به الرب».","2:16":"فجاءوا مسرعين, ووجدوا مريم ويوسف والطفل مضجعا في المذود.","2:17":"فلما رأوه أخبروا بالكلام الذي قيل لهم عن هذا الصبي.","2:18":"وكل الذين سمعوا تعجبوا مما قيل لهم من الرعاة.","2:19":"وأما مريم فكانت تحفظ جميع هذا الكلام متفكرة به في قلبها.","2:20":"ثم رجع الرعاة وهم يمجدون الله ويسبحونه على كل ما سمعوه ورأوه كما قيل لهم.","2:21":"ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع, كما تسمى من الملاك قبل أن حبل به في البطن.","2:22":"ولما تمت أيام تطهيرها, حسب شريعة موسى, صعدوا به إلى أورشليم ليقدموه للرب","2:23":"كما هو مكتوب في ناموس الرب: أن كل ذكر فاتح رحم يدعى قدوسا للرب.","2:24":"ولكي يقدموا ذبيحة كما قيل في ناموس الرب زوج يمام أو فرخي حمام.","2:25":"وكان رجل في أورشليم اسمه سمعان, وهذا الرجل كان بارا تقيا ينتظر تعزية إسرائيل, والروح القدس كان عليه.","2:26":"وكان قد أوحي إليه بالروح القدس أنه لا يرى الموت قبل أن يرى مسيح الرب.","2:27":"فأتى بالروح إلى الهيكل. وعندما دخل بالصبي يسوع أبواه, ليصنعا له حسب عادة الناموس","2:28":"أخذه على ذراعيه وبارك الله وقال:","2:29":"«الآن تطلق عبدك يا سيد حسب قولك بسلام","2:30":"لأن عيني قد أبصرتا خلاصك","2:31":"الذي أعددته قدام وجه جميع الشعوب.","2:32":"نور إعلان للأمم, ومجدا لشعبك إسرائيل».","2:33":"وكان يوسف وأمه يتعجبان مما قيل فيه.","2:34":"وباركهما سمعان, وقال لمريم أمه: «ها إن هذا قد وضع لسقوط وقيام كثيرين في إسرائيل, ولعلامة تقاوم.","2:35":"وأنت أيضا يجوز في نفسك سيف, لتعلن أفكار من قلوب كثيرة».","2:36":"وكانت نبية, حنة بنت فنوئيل من سبط أشير, وهي متقدمة في أيام كثيرة, قد عاشت مع زوج سبع سنين بعد بكوريتها.","2:37":"وهي أرملة نحو أربع وثمانين سنة, لا تفارق الهيكل, عابدة بأصوام وطلبات ليلا ونهارا.","2:38":"فهي في تلك الساعة وقفت تسبح الرب, وتكلمت عنه مع جميع المنتظرين فداء في أورشليم.","2:39":"ولما أكملوا كل شيء حسب ناموس الرب, رجعوا إلى الجليل إلى مدينتهم الناصرة.","2:40":"وكان الصبي ينمو ويتقوى بالروح, ممتلئا حكمة, وكانت نعمة الله عليه.","2:41":"وكان أبواه يذهبان كل سنة إلى أورشليم في عيد الفصح.","2:42":"ولما كانت له اثنتا عشرة سنة صعدوا إلى أورشليم كعادة العيد.","2:43":"وبعدما أكملوا الأيام بقي عند رجوعهما الصبي يسوع في أورشليم, ويوسف وأمه لم يعلما.","2:44":"وإذ ظناه بين الرفقة, ذهبا مسيرة يوم, وكانا يطلبانه بين الأقرباء والمعارف.","2:45":"ولما لم يجداه رجعا إلى أورشليم يطلبانه.","2:46":"وبعد ثلاثة أيام وجداه في الهيكل, جالسا في وسط المعلمين, يسمعهم ويسألهم.","2:47":"وكل الذين سمعوه بهتوا من فهمه وأجوبته.","2:48":"فلما أبصراه اندهشا. وقالت له أمه: «يا بني, لماذا فعلت بنا هكذا؟ هوذا أبوك وأنا كنا نطلبك معذبين!»","2:49":"فقال لهما: «لماذا كنتما تطلبانني؟ ألم تعلما أنه ينبغي أن أكون في ما لأبي؟».","2:50":"فلم يفهما الكلام الذي قاله لهما.","2:51":"ثم نزل معهما وجاء إلى الناصرة وكان خاضعا لهما. وكانت أمه تحفظ جميع هذه الأمور في قلبها.","2:52":"وأما يسوع فكان يتقدم في الحكمة والقامة والنعمة, عند الله والناس.","3:1":"وفي السنة الخامسة عشرة من سلطنة طيباريوس قيصر, إذ كان بيلاطس البنطي واليا على اليهودية, وهيرودس رئيس ربع على الجليل, وفيلبس أخوه رئيس ربع على إيطورية وكورة تراخونيتس, وليسانيوس رئيس ربع على الأبلية","3:2":"في أيام رئيس الكهنة حنان وقيافا, كانت كلمة الله على يوحنا بن زكريا في البرية","3:3":"فجاء إلى جميع الكورة المحيطة بالأردن يكرز بمعمودية التوبة لمغفرة الخطايا","3:4":"كما هو مكتوب في سفر أقوال إشعياء النبي القائل: «صوت صارخ في البرية أعدوا طريق الرب, اصنعوا سبله مستقيمة.","3:5":"كل واد يمتلئ, وكل جبل وأكمة ينخفض, وتصير المعوجات مستقيمة, والشعاب طرقا سهلة","3:6":"ويبصر كل بشر خلاص الله».","3:7":"وكان يقول للجموع الذين خرجوا ليعتمدوا منه: «يا أولاد الأفاعي, من أراكم أن تهربوا من الغضب الآتي؟","3:8":"فاصنعوا أثمارا تليق بالتوبة. ولا تبتدئوا تقولون في أنفسكم: لنا إبراهيم أبا. لأني أقول لكم إن الله قادر أن يقيم من هذه الحجارة أولادا لإبراهيم.","3:9":"والآن قد وضعت الفأس على أصل الشجر, فكل شجرة لا تصنع ثمرا جيدا تقطع وتلقى في النار».","3:10":"وسأله الجموع قائلين: «فماذا نفعل؟»","3:11":"فأجاب وقال لهم: «من له ثوبان فليعط من ليس له, ومن له طعام فليفعل هكذا».","3:12":"وجاء عشارون أيضا ليعتمدوا فقالوا له: «يا معلم ماذا نفعل؟»","3:13":"فقال لهم: «لا تستوفوا أكثر مما فرض لكم».","3:14":"وسأله جنديون أيضا قائلين: «وماذا نفعل نحن؟» فقال لهم: «لا تظلموا أحدا, ولا تشوا بأحد, واكتفوا بعلائفكم».","3:15":"وإذ كان الشعب ينتظر, والجميع يفكرون في قلوبهم عن يوحنا لعله المسيح","3:16":"أجاب يوحنا الجميع قائلا: «أنا أعمدكم بماء, ولكن يأتي من هو أقوى مني, الذي لست أهلا أن أحل سيور حذائه. هو سيعمدكم بالروح القدس ونار.","3:17":"الذي رفشه في يده, وسينقي بيدره, ويجمع القمح إلى مخزنه, وأما التبن فيحرقه بنار لا تطفأ».","3:18":"وبأشياء أخر كثيرة كان يعظ الشعب ويبشرهم.","3:19":"أما هيرودس رئيس الربع فإذ توبخ منه لسبب هيروديا امرأة فيلبس أخيه, ولسبب جميع الشرور التي كان هيرودس يفعلها","3:20":"زاد هذا أيضا على الجميع أنه حبس يوحنا في السجن.","3:21":"ولما اعتمد جميع الشعب اعتمد يسوع أيضا. وإذ كان يصلي انفتحت السماء","3:22":"ونزل عليه الروح القدس بهيئة جسمية مثل حمامة. وكان صوت من السماء قائلا: «أنت ابني الحبيب, بك سررت!».","3:23":"ولما ابتدأ يسوع كان له نحو ثلاثين سنة, وهو على ما كان يظن ابن يوسف, بن هالي","3:24":"بن متثات, بن لاوي, بن ملكي, بن ينا, بن يوسف","3:25":"بن متاثيا, بن عاموص, بن ناحوم, بن حسلي, بن نجاي","3:26":"بن مآث, بن متاثيا, بن شمعي, بن يوسف, بن يهوذا","3:27":"بن يوحنا, بن ريسا, بن زربابل, بن شألتيئيل, بن نيري","3:28":"بن ملكي, بن أدي, بن قصم, بن ألمودام, بن عير","3:29":"بن يوسي, بن أليعازر, بن يوريم, بن متثات, بن لاوي","3:30":"بن شمعون, بن يهوذا, بن يوسف, بن يونان, بن ألياقيم","3:31":"بن مليا, بن مينان, بن متاثا, بن ناثان, بن داود","3:32":"بن يسى, بن عوبيد, بن بوعز, بن سلمون, بن نحشون","3:33":"بن عميناداب, بن أرام, بن حصرون, بن فارص, بن يهوذا","3:34":"بن يعقوب, بن إسحاق, بن إبراهيم, بن تارح, بن ناحور","3:35":"بن سروج, بن رعو, بن فالج, بن عابر, بن شالح","3:36":"بن قينان, بن أرفكشاد, بن سام, بن نوح, بن لامك","3:37":"بن متوشالح, بن أخنوخ, بن يارد, بن مهللئيل, بن قينان","3:38":"بن أنوش, بن شيت, بن آدم, ابن الله.","4:1":"أما يسوع فرجع من الأردن ممتلئا من الروح القدس, وكان يقتاد بالروح في البرية","4:2":"أربعين يوما يجرب من إبليس. ولم يأكل شيئا في تلك الأيام. ولما تمت جاع أخيرا.","4:3":"وقال له إبليس: «إن كنت ابن الله, فقل لهذا الحجر أن يصير خبزا».","4:4":"فأجابه يسوع قائلا: «مكتوب أن ليس بالخبز وحده يحيا الإنسان, بل بكل كلمة من الله».","4:5":"ثم أصعده إبليس إلى جبل عال وأراه جميع ممالك المسكونة في لحظة من الزمان.","4:6":"وقال له إبليس: «لك أعطي هذا السلطان كله ومجدهن, لأنه إلي قد دفع, وأنا أعطيه لمن أريد.","4:7":"فإن سجدت أمامي يكون لك الجميع».","4:8":"فأجابه يسوع وقال: «اذهب يا شيطان! إنه مكتوب: للرب إلهك تسجد وإياه وحده تعبد».","4:9":"ثم جاء به إلى أورشليم, وأقامه على جناح الهيكل وقال له: «إن كنت ابن الله فاطرح نفسك من هنا إلى أسفل","4:10":"لأنه مكتوب: أنه يوصي ملائكته بك لكي يحفظوك","4:11":"وأنهم على أياديهم يحملونك لكي لا تصدم بحجر رجلك».","4:12":"فأجاب يسوع وقال له: «إنه قيل: لا تجرب الرب إلهك».","4:13":"ولما أكمل إبليس كل تجربة فارقه إلى حين.","4:14":"ورجع يسوع بقوة الروح إلى الجليل, وخرج خبر عنه في جميع الكورة المحيطة.","4:15":"وكان يعلم في مجامعهم ممجدا من الجميع.","4:16":"وجاء إلى الناصرة حيث كان قد تربى. ودخل المجمع حسب عادته يوم السبت وقام ليقرأ","4:17":"فدفع إليه سفر إشعياء النبي. ولما فتح السفر وجد الموضع الذي كان مكتوبا فيه:","4:18":"«روح الرب علي, لأنه مسحني لأبشر المساكين, أرسلني لأشفي المنكسري القلوب, لأنادي للمأسورين بالإطلاق وللعمي بالبصر, وأرسل المنسحقين في الحرية","4:19":"وأكرز بسنة الرب المقبولة».","4:20":"ثم طوى السفر وسلمه إلى الخادم, وجلس. وجميع الذين في المجمع كانت عيونهم شاخصة إليه.","4:21":"فابتدأ يقول لهم: «إنه اليوم قد تم هذا المكتوب في مسامعكم».","4:22":"وكان الجميع يشهدون له ويتعجبون من كلمات النعمة الخارجة من فمه, ويقولون: «أليس هذا ابن يوسف؟»","4:23":"فقال لهم: «على كل حال تقولون لي هذا المثل: أيها الطبيب اشف نفسك. كم سمعنا أنه جرى في كفرناحوم, فافعل ذلك هنا أيضا في وطنك","4:24":"وقال: «الحق أقول لكم إنه ليس نبي مقبولا في وطنه.","4:25":"وبالحق أقول لكم إن أرامل كثيرة كن في إسرائيل في أيام إيليا حين أغلقت السماء مدة ثلاث سنين وستة أشهر, لما كان جوع عظيم في الأرض كلها","4:26":"ولم يرسل إيليا إلى واحدة منها, إلا إلى امرأة أرملة, إلى صرفة صيداء.","4:27":"وبرص كثيرون كانوا في إسرائيل في زمان أليشع النبي, ولم يطهر واحد منهم إلا نعمان السرياني».","4:28":"فامتلأ غضبا جميع الذين في المجمع حين سمعوا هذا","4:29":"فقاموا وأخرجوه خارج المدينة, وجاءوا به إلى حافة الجبل الذي كانت مدينتهم مبنية عليه حتى يطرحوه إلى أسفل.","4:30":"أما هو فجاز في وسطهم ومضى.","4:31":"وانحدر إلى كفرناحوم, مدينة من الجليل, وكان يعلمهم في السبوت.","4:32":"فبهتوا من تعليمه, لأن كلامه كان بسلطان.","4:33":"وكان في المجمع رجل به روح شيطان نجس, فصرخ بصوت عظيم:","4:34":"«قائلا آه ما لنا ولك يا يسوع الناصري! أتيت لتهلكنا! أنا أعرفك من أنت: قدوس الله».","4:35":"فانتهره يسوع قائلا: «اخرس واخرج منه». فصرعه الشيطان في الوسط وخرج منه ولم يضره شيئا.","4:36":"فوقعت دهشة على الجميع, وكانوا يخاطبون بعضهم بعضا قائلين: «ما هذه الكلمة! لأنه بسلطان وقوة يأمر الأرواح النجسة فتخرج».","4:37":"وخرج صيت عنه إلى كل موضع في الكورة المحيطة.","4:38":"ولما قام من المجمع دخل بيت سمعان. وكانت حماة سمعان قد أخذتها حمى شديدة. فسألوه من أجلها.","4:39":"فوقف فوقها وانتهر الحمى فتركتها! وفي الحال قامت وصارت تخدمهم.","4:40":"وعند غروب الشمس, جميع الذين كان عندهم سقماء بأمراض مختلفة قدموهم إليه, فوضع يديه على كل واحد منهم وشفاهم.","4:41":"وكانت شياطين أيضا تخرج من كثيرين وهي تصرخ وتقول: «أنت المسيح ابن الله!» فانتهرهم ولم يدعهم يتكلمون, لأنهم عرفوه أنه المسيح.","4:42":"ولما صار النهار خرج وذهب إلى موضع خلاء, وكان الجموع يفتشون عليه. فجاءوا إليه وأمسكوه لئلا يذهب عنهم.","4:43":"فقال لهم: «إنه ينبغي لي أن أبشر المدن الأخر أيضا بملكوت الله, لأني لهذا قد أرسلت».","4:44":"فكان يكرز في مجامع الجليل.","5:1":"وإذ كان الجمع يزدحم عليه ليسمع كلمة الله, كان واقفا عند بحيرة جنيسارت.","5:2":"فرأى سفينتين واقفتين عند البحيرة, والصيادون قد خرجوا منهما وغسلوا الشباك.","5:3":"فدخل إحدى السفينتين التي كانت لسمعان, وسأله أن يبعد قليلا عن البر. ثم جلس وصار يعلم الجموع من السفينة.","5:4":"ولما فرغ من الكلام قال لسمعان: «ابعد إلى العمق وألقوا شباككم للصيد».","5:5":"فأجاب سمعان وقال له: «يا معلم, قد تعبنا الليل كله ولم نأخذ شيئا. ولكن على كلمتك ألقي الشبكة».","5:6":"ولما فعلوا ذلك أمسكوا سمكا كثيرا جدا, فصارت شبكتهم تتخرق.","5:7":"فأشاروا إلى شركائهم الذين في السفينة الأخرى أن يأتوا ويساعدوهم. فأتوا وملأوا السفينتين حتى أخذتا في الغرق.","5:8":"فلما رأى سمعان بطرس ذلك خر عند ركبتي يسوع قائلا: «اخرج من سفينتي يارب, لأني رجل خاطئ».","5:9":"إذ اعترته وجميع الذين معه دهشة على صيد السمك الذي أخذوه.","5:10":"وكذلك أيضا يعقوب ويوحنا ابنا زبدي اللذان كانا شريكي سمعان. فقال يسوع لسمعان: «لا تخف! من الآن تكون تصطاد الناس!»","5:11":"ولما جاءوا بالسفينتين إلى البر تركوا كل شيء وتبعوه.","5:12":"وكان في إحدى المدن. فإذا رجل مملوء برصا. فلما رأى يسوع خر على وجهه وطلب إليه قائلا: «يا سيد, إن أردت تقدر أن تطهرني».","5:13":"فمد يده ولمسه قائلا: «أريد, فاطهر». وللوقت ذهب عنه البرص.","5:14":"فأوصاه أن لا يقول لأحد. بل «امض وأر نفسك للكاهن, وقدم عن تطهيرك كما أمر موسى شهادة لهم».","5:15":"فذاع الخبر عنه أكثر. فاجتمع جموع كثيرة لكي يسمعوا ويشفوا به من أمراضهم.","5:16":"وأما هو فكان يعتزل في البراري ويصلي.","5:17":"وفي أحد الأيام كان يعلم, وكان فريسيون ومعلمون للناموس جالسين وهم قد أتوا من كل قرية من الجليل واليهودية وأورشليم. وكانت قوة الرب لشفائهم.","5:18":"وإذا برجال يحملون على فراش إنسانا مفلوجا, وكانوا يطلبون أن يدخلوا به ويضعوه أمامه.","5:19":"ولما لم يجدوا من أين يدخلون به لسبب الجمع, صعدوا على السطح ودلوه مع الفراش من بين الأجر إلى الوسط قدام يسوع.","5:20":"فلما رأى إيمانهم قال له: «أيها الإنسان, مغفورة لك خطاياك».","5:21":"فابتدأ الكتبة والفريسيون يفكرون قائلين: «من هذا الذي يتكلم بتجاديف؟ من يقدر أن يغفر خطايا إلا الله وحده؟»","5:22":"فشعر يسوع بأفكارهم, وأجاب وقال لهم: «ماذا تفكرون في قلوبكم؟","5:23":"أيما أيسر: أن يقال مغفورة لك خطاياك, أم أن يقال قم وامش.","5:24":"ولكن لكي تعلموا أن لابن الإنسان سلطانا على الأرض أن يغفر الخطايا» - قال للمفلوج: «لك أقول قم واحمل فراشك واذهب إلى بيتك».","5:25":"ففي الحال قام أمامهم, وحمل ما كان مضطجعا عليه, ومضى إلى بيته وهو يمجد الله.","5:26":"فأخذت الجميع حيرة ومجدوا الله, وامتلأوا خوفا قائلين: «إننا قد رأينا اليوم عجائب!».","5:27":"وبعد هذا خرج فنظر عشارا اسمه لاوي جالسا عند مكان الجباية, فقال له: «اتبعني».","5:28":"فترك كل شيء وقام وتبعه.","5:29":"وصنع له لاوي ضيافة كبيرة في بيته. والذين كانوا متكئين معهم كانوا جمعا كثيرا من عشارين وآخرين.","5:30":"فتذمر كتبتهم والفريسيون على تلاميذه قائلين: «لماذا تأكلون وتشربون مع عشارين وخطاة؟»","5:31":"فأجاب يسوع وقال لهم: «لا يحتاج الأصحاء إلى طبيب, بل المرضى.","5:32":"لم آت لأدعو أبرارا بل خطاة إلى التوبة».","5:33":"وقالوا له: «لماذا يصوم تلاميذ يوحنا كثيرا ويقدمون طلبات, وكذلك تلاميذ الفريسيين أيضا, وأما تلاميذك فيأكلون ويشربون؟»","5:34":"فقال لهم: «أتقدرون أن تجعلوا بني العرس يصومون ما دام العريس معهم؟","5:35":"ولكن ستأتي أيام حين يرفع العريس عنهم, فحينئذ يصومون في تلك الأيام».","5:36":"وقال لهم أيضا مثلا: «ليس أحد يضع رقعة من ثوب جديد على ثوب عتيق, وإلا فالجديد يشقه, والعتيق لا توافقه الرقعة التي من الجديد.","5:37":"وليس أحد يجعل خمرا جديدة في زقاق عتيقة لئلا تشق الخمر الجديدة الزقاق, فهي تهرق والزقاق تتلف.","5:38":"بل يجعلون خمرا جديدة في زقاق جديدة, فتحفظ جميعا.","5:39":"وليس أحد إذا شرب العتيق يريد للوقت الجديد, لأنه يقول: العتيق أطيب».","6:1":"وفي السبت الثاني بعد الأول اجتاز بين الزروع. وكان تلاميذه يقطفون السنابل ويأكلون وهم يفركونها بأيديهم.","6:2":"فقال لهم قوم من الفريسيين: «لماذا تفعلون ما لا يحل فعله في السبوت؟»","6:3":"فأجاب يسوع وقال لهم: «أما قرأتم ولا هذا الذي فعله داود, حين جاع هو والذين كانوا معه","6:4":"كيف دخل بيت الله وأخذ خبز التقدمة وأكل, وأعطى الذين معه أيضا, الذي لا يحل أكله إلا للكهنة فقط؟»","6:5":"وقال لهم: «إن ابن الإنسان هو رب السبت أيضا».","6:6":"وفي سبت آخر دخل المجمع وصار يعلم. وكان هناك رجل يده اليمنى يابسة","6:7":"وكان الكتبة والفريسيون يراقبونه: هل يشفي في السبت, لكي يجدوا عليه شكاية.","6:8":"أما هو فعلم أفكارهم, وقال للرجل الذي يده يابسة: «قم وقف في الوسط». فقام ووقف.","6:9":"ثم قال لهم يسوع: «أسألكم شيئا: هل يحل في السبت فعل الخير أو فعل الشر؟ تخليص نفس أو إهلاكها؟».","6:10":"ثم نظر حوله إلى جميعهم وقال للرجل: «مد يدك». ففعل هكذا. فعادت يده صحيحة كالأخرى.","6:11":"فامتلأوا حمقا وصاروا يتكالمون فيما بينهم: ماذا يفعلون بيسوع؟","6:12":"وفي تلك الأيام خرج إلى الجبل ليصلي. وقضى الليل كله في الصلاة لله.","6:13":"ولما كان النهار دعا تلاميذه, واختار منهم اثني عشر, الذين سماهم أيضا «رسلا»:","6:14":"سمعان الذي سماه أيضا بطرس وأندراوس أخاه. يعقوب ويوحنا. فيلبس وبرثولماوس.","6:15":"متى وتوما. يعقوب بن حلفى وسمعان الذي يدعى الغيور.","6:16":"يهوذا أخا يعقوب, ويهوذا الإسخريوطي الذي صار مسلما أيضا.","6:17":"ونزل معهم ووقف في موضع سهل, هو وجمع من تلاميذه, وجمهور كثير من الشعب, من جميع اليهودية وأورشليم وساحل صور وصيداء, الذين جاءوا ليسمعوه ويشفوا من أمراضهم","6:18":"والمعذبون من أرواح نجسة. وكانوا يبرأون.","6:19":"وكل الجمع طلبوا أن يلمسوه, لأن قوة كانت تخرج منه وتشفي الجميع.","6:20":"ورفع عينيه إلى تلاميذه وقال: «طوباكم أيها المساكين, لأن لكم ملكوت الله.","6:21":"طوباكم أيها الجياع الآن, لأنكم تشبعون. طوباكم أيها الباكون الآن, لأنكم ستضحكون.","6:22":"طوباكم إذا أبغضكم الناس, وإذا أفرزوكم وعيروكم, وأخرجوا اسمكم كشرير من أجل ابن الإنسان.","6:23":"افرحوا في ذلك اليوم وتهللوا, فهوذا أجركم عظيم في السماء. لأن آباءهم هكذا كانوا يفعلون بالأنبياء.","6:24":"ولكن ويل لكم أيها الأغنياء, لأنكم قد نلتم عزاءكم.","6:25":"ويل لكم أيها الشباعى, لأنكم ستجوعون. ويل لكم أيها الضاحكون الآن, لأنكم ستحزنون وتبكون.","6:26":"ويل لكم إذا قال فيكم جميع الناس حسنا. لأنه هكذا كان آباؤهم يفعلون بالأنبياء الكذبة.","6:27":"«لكني أقول لكم أيها السامعون: أحبوا أعداءكم, أحسنوا إلى مبغضيكم","6:28":"باركوا لاعنيكم, وصلوا لأجل الذين يسيئون إليكم.","6:29":"من ضربك على خدك فاعرض له الآخر أيضا, ومن أخذ رداءك فلا تمنعه ثوبك أيضا.","6:30":"وكل من سألك فأعطه, ومن أخذ الذي لك فلا تطالبه.","6:31":"وكما تريدون أن يفعل الناس بكم افعلوا أنتم أيضا بهم هكذا.","6:32":"وإن أحببتم الذين يحبونكم, فأي فضل لكم؟ فإن الخطاة أيضا يحبون الذين يحبونهم.","6:33":"وإذا أحسنتم إلى الذين يحسنون إليكم, فأي فضل لكم؟ فإن الخطاة أيضا يفعلون هكذا.","6:34":"وإن أقرضتم الذين ترجون أن تستردوا منهم, فأي فضل لكم؟ فإن الخطاة أيضا يقرضون الخطاة لكي يستردوا منهم المثل.","6:35":"بل أحبوا أعداءكم, وأحسنوا وأقرضوا وأنتم لا ترجون شيئا, فيكون أجركم عظيما وتكونوا بني العلي, فإنه منعم على غير الشاكرين والأشرار.","6:36":"فكونوا رحماء كما أن أباكم أيضا رحيم.","6:37":"ولا تدينوا فلا تدانوا. لا تقضوا على أحد فلا يقضى عليكم. اغفروا يغفر لكم.","6:38":"أعطوا تعطوا, كيلا جيدا ملبدا مهزوزا فائضا يعطون في أحضانكم. لأنه بنفس الكيل الذي به تكيلون يكال لكم».","6:39":"وضرب لهم مثلا: «هل يقدر أعمى أن يقود أعمى؟ أما يسقط الاثنان في حفرة؟","6:40":"ليس التلميذ أفضل من معلمه, بل كل من صار كاملا يكون مثل معلمه.","6:41":"لماذا تنظر القذى الذي في عين أخيك, وأما الخشبة التي في عينك فلا تفطن لها؟","6:42":"أو كيف تقدر أن تقول لأخيك: يا أخي, دعني أخرج القذى الذي في عينك, وأنت لا تنظر الخشبة التي في عينك. يا مرائي! أخرج أولا الخشبة من عينك, وحينئذ تبصر جيدا أن تخرج القذى الذي في عين أخيك.","6:43":"لأنه ما من شجرة جيدة تثمر ثمرا رديا, ولا شجرة ردية تثمر ثمرا جيدا.","6:44":"لأن كل شجرة تعرف من ثمرها. فإنهم لا يجتنون من الشوك تينا, ولا يقطفون من العليق عنبا.","6:45":"الإنسان الصالح من كنز قلبه الصالح يخرج الصلاح, والإنسان الشرير من كنز قلبه الشرير يخرج الشر. فإنه من فضلة القلب يتكلم فمه.","6:46":"ولماذا تدعونني: يا رب يا رب وأنتم لا تفعلون ما أقوله؟","6:47":"كل من يأتي إلي ويسمع كلامي ويعمل به أريكم من يشبه","6:48":"يشبه إنسانا بنى بيتا, وحفر وعمق ووضع الأساس على الصخر. فلما حدث سيل صدم النهر ذلك البيت, فلم يقدر أن يزعزعه, لأنه كان مؤسسا على الصخر.","6:49":"وأما الذي يسمع ولا يعمل, فيشبه إنسانا بنى بيته على الأرض من دون أساس, فصدمه النهر فسقط حالا, وكان خراب ذلك البيت عظيما».","7:1":"ولما أكمل أقواله كلها في مسامع الشعب دخل كفرناحوم.","7:2":"وكان عبد لقائد مئة, مريضا مشرفا على الموت, وكان عزيزا عنده.","7:3":"فلما سمع عن يسوع, أرسل إليه شيوخ اليهود يسأله أن يأتي ويشفي عبده.","7:4":"فلما جاءوا إلى يسوع طلبوا إليه باجتهاد قائلين: «إنه مستحق أن يفعل له هذا","7:5":"لأنه يحب أمتنا, وهو بنى لنا المجمع».","7:6":"فذهب يسوع معهم. وإذ كان غير بعيد عن البيت, أرسل إليه قائد المئة أصدقاء يقول له: «يا سيد, لا تتعب. لأني لست مستحقا أن تدخل تحت سقفي.","7:7":"لذلك لم أحسب نفسي أهلا أن آتي إليك. لكن قل كلمة فيبرأ غلامي.","7:8":"لأني أنا أيضا إنسان مرتب تحت سلطان, لي جند تحت يدي. وأقول لهذا: اذهب فيذهب, ولآخر: ائت فيأتي, ولعبدي: افعل هذا فيفعل».","7:9":"ولما سمع يسوع هذا تعجب منه, والتفت إلى الجمع الذي يتبعه وقال: «أقول لكم: لم أجد ولا في إسرائيل إيمانا بمقدار هذا».","7:10":"ورجع المرسلون إلى البيت, فوجدوا العبد المريض قد صح.","7:11":"وفي اليوم التالي ذهب إلى مدينة تدعى نايين, وذهب معه كثيرون من تلاميذه وجمع كثير.","7:12":"فلما اقترب إلى باب المدينة, إذا ميت محمول, ابن وحيد لأمه, وهي أرملة ومعها جمع كثير من المدينة.","7:13":"فلما رآها الرب تحنن عليها, وقال لها: «لا تبكي».","7:14":"ثم تقدم ولمس النعش, فوقف الحاملون. فقال: «أيها الشاب, لك أقول قم».","7:15":"فجلس الميت وابتدأ يتكلم, فدفعه إلى أمه.","7:16":"فأخذ الجميع خوف, ومجدوا الله قائلين: «قد قام فينا نبي عظيم, وافتقد الله شعبه».","7:17":"وخرج هذا الخبر عنه في كل اليهودية وفي جميع الكورة المحيطة.","7:18":"فأخبر يوحنا تلاميذه بهذا كله.","7:19":"فدعا يوحنا اثنين من تلاميذه, وأرسل إلى يسوع قائلا: «أنت هو الآتي أم ننتظر آخر؟»","7:20":"فلما جاء إليه الرجلان قالا: «يوحنا المعمدان قد أرسلنا إليك قائلا: أنت هو الآتي أم ننتظر آخر؟»","7:21":"وفي تلك الساعة شفى كثيرين من أمراض وأدواء وأرواح شريرة, ووهب البصر لعميان كثيرين.","7:22":"فأجاب يسوع وقال لهما: «اذهبا وأخبرا يوحنا بما رأيتما وسمعتما: إن العمي يبصرون, والعرج يمشون, والبرص يطهرون, والصم يسمعون, والموتى يقومون, والمساكين يبشرون.","7:23":"وطوبى لمن لا يعثر في».","7:24":"فلما مضى رسولا يوحنا, ابتدأ يقول للجموع عن يوحنا: «ماذا خرجتم إلى البرية لتنظروا؟ أقصبة تحركها الريح؟","7:25":"بل ماذا خرجتم لتنظروا؟ أإنسانا لابسا ثيابا ناعمة؟ هوذا الذين في اللباس الفاخر والتنعم هم في قصور الملوك.","7:26":"بل ماذا خرجتم لتنظروا؟ أنبيا؟ نعم, أقول لكم وأفضل من نبي!","7:27":"هذا هو الذي كتب عنه: ها أنا أرسل أمام وجهك ملاكي الذي يهيئ طريقك قدامك!","7:28":"لأني أقول لكم: إنه بين المولودين من النساء ليس نبي أعظم من يوحنا المعمدان, ولكن الأصغر في ملكوت الله أعظم منه».","7:29":"وجميع الشعب إذ سمعوا والعشارون برروا الله معتمدين بمعمودية يوحنا.","7:30":"وأما الفريسيون والناموسيون فرفضوا مشورة الله من جهة أنفسهم, غير معتمدين منه.","7:31":"ثم قال الرب: «فبمن أشبه أناس هذا الجيل وماذا يشبهون؟","7:32":"يشبهون أولادا جالسين في السوق ينادون بعضهم بعضا ويقولون: زمرنا لكم فلم ترقصوا. نحنا لكم فلم تبكوا.","7:33":"لأنه جاء يوحنا المعمدان لا يأكل خبزا ولا يشرب خمرا, فتقولون: به شيطان.","7:34":"جاء ابن الإنسان يأكل ويشرب, فتقولون: هوذا إنسان أكول وشريب خمر, محب للعشارين والخطاة.","7:35":"والحكمة تبررت من جميع بنيها».","7:36":"وسأله واحد من الفريسيين أن يأكل معه, فدخل بيت الفريسي واتكأ.","7:37":"وإذا امرأة في المدينة كانت خاطئة, إذ علمت أنه متكئ في بيت الفريسي, جاءت بقارورة طيب","7:38":"ووقفت عند قدميه من ورائه باكية, وابتدأت تبل قدميه بالدموع, وكانت تمسحهما بشعر رأسها, وتقبل قدميه وتدهنهما بالطيب.","7:39":"فلما رأى الفريسي الذي دعاه ذلك, تكلم في نفسه قائلا: «لو كان هذا نبيا, لعلم من هذه الامرأة التي تلمسه وما هي! إنها خاطئة».","7:40":"فأجاب يسوع وقال له: «يا سمعان عندي شيء أقوله لك». فقال: «قل يا معلم».","7:41":"«كان لمداين مديونان. على الواحد خمس مئة دينار وعلى الآخر خمسون.","7:42":"وإذ لم يكن لهما ما يوفيان سامحهما جميعا. فقل: أيهما يكون أكثر حبا له؟»","7:43":"فأجاب سمعان وقال: «أظن الذي سامحه بالأكثر». فقال له: «بالصواب حكمت».","7:44":"ثم التفت إلى المرأة وقال لسمعان: «أتنظر هذه المرأة؟ إني دخلت بيتك, وماء لأجل رجلي لم تعط. وأما هي فقد غسلت رجلي بالدموع ومسحتهما بشعر رأسها.","7:45":"قبلة لم تقبلني, وأما هي فمنذ دخلت لم تكف عن تقبيل رجلي.","7:46":"بزيت لم تدهن رأسي, وأما هي فقد دهنت بالطيب رجلي.","7:47":"من أجل ذلك أقول لك: قد غفرت خطاياها الكثيرة, لأنها أحبت كثيرا. والذي يغفر له قليل يحب قليلا».","7:48":"ثم قال لها: «مغفورة لك خطاياك».","7:49":"فابتدأ المتكئون معه يقولون في أنفسهم: «من هذا الذي يغفر خطايا أيضا؟».","7:50":"فقال للمرأة: «إيمانك قد خلصك! اذهبي بسلام».","8:1":"وعلى أثر ذلك كان يسير في مدينة وقرية يكرز ويبشر بملكوت الله, ومعه الاثنا عشر.","8:2":"وبعض النساء كن قد شفين من أرواح شريرة وأمراض: مريم التي تدعى المجدلية التي خرج منها سبعة شياطين","8:3":"ويونا امرأة خوزي وكيل هيرودس, وسوسنة, وأخر كثيرات كن يخدمنه من أموالهن.","8:4":"فلما اجتمع جمع كثير أيضا من الذين جاءوا إليه من كل مدينة, قال بمثل:","8:5":"«خرج الزارع ليزرع زرعه. وفيما هو يزرع سقط بعض على الطريق, فانداس وأكلته طيور السماء.","8:6":"وسقط آخر على الصخر, فلما نبت جف لأنه لم تكن له رطوبة.","8:7":"وسقط آخر في وسط الشوك, فنبت معه الشوك وخنقه.","8:8":"وسقط آخر في الأرض الصالحة, فلما نبت صنع ثمرا مئة ضعف». قال هذا ونادى: «من له أذنان للسمع فليسمع!».","8:9":"فسأله تلاميذه قائلين: «ما عسى أن يكون هذا المثل؟».","8:10":"فقال: «لكم قد أعطي أن تعرفوا أسرار ملكوت الله, وأما للباقين فبأمثال, حتى إنهم مبصرين لا يبصرون, وسامعين لا يفهمون.","8:11":"وهذا هو المثل: الزرع هو كلام الله","8:12":"والذين على الطريق هم الذين يسمعون, ثم يأتي إبليس وينزع الكلمة من قلوبهم لئلا يؤمنوا فيخلصوا.","8:13":"والذين على الصخر هم الذين متى سمعوا يقبلون الكلمة بفرح. وهؤلاء ليس لهم أصل, فيؤمنون إلى حين, وفي وقت التجربة يرتدون.","8:14":"والذي سقط بين الشوك هم الذين يسمعون, ثم يذهبون فيختنقون من هموم الحياة وغناها ولذاتها, ولا ينضجون ثمرا.","8:15":"والذي في الأرض الجيدة, هو الذين يسمعون الكلمة فيحفظونها في قلب جيد صالح, ويثمرون بالصبر.","8:16":"«وليس أحد يوقد سراجا ويغطيه بإناء أو يضعه تحت سرير, بل يضعه على منارة, لينظر الداخلون النور.","8:17":"لأنه ليس خفي لا يظهر, ولا مكتوم لا يعلم ويعلن.","8:18":"فانظروا كيف تسمعون! لأن من له سيعطى, ومن ليس له فالذي يظنه له يؤخذ منه».","8:19":"وجاء إليه أمه وإخوته, ولم يقدروا أن يصلوا إليه لسبب الجمع.","8:20":"فأخبروه قائلين: «أمك وإخوتك واقفون خارجا, يريدون أن يروك».","8:21":"فأجاب وقال لهم: «أمي وإخوتي هم الذين يسمعون كلمة الله ويعملون بها».","8:22":"وفي أحد الأيام دخل سفينة هو وتلاميذه, فقال لهم: «لنعبر إلى عبر البحيرة». فأقلعوا.","8:23":"وفيما هم سائرون نام. فنزل نوء ريح في البحيرة, وكانوا يمتلئون ماء وصاروا في خطر.","8:24":"فتقدموا وأيقظوه قائلين: «يا معلم, يا معلم, إننا نهلك!». فقام وانتهر الريح وتموج الماء, فانتهيا وصار هدو.","8:25":"ثم قال لهم: «أين إيمانكم؟» فخافوا وتعجبوا قائلين فيما بينهم: «من هو هذا؟ فإنه يأمر الرياح أيضا والماء فتطيعه!».","8:26":"وساروا إلى كورة الجدريين التي هي مقابل الجليل.","8:27":"ولما خرج إلى الأرض استقبله رجل من المدينة كان فيه شياطين منذ زمان طويل, وكان لا يلبس ثوبا, ولا يقيم في بيت, بل في القبور.","8:28":"فلما رأى يسوع صرخ وخر له, وقال بصوت عظيم: «ما لي ولك يا يسوع ابن الله العلي! أطلب منك أن لا تعذبني».","8:29":"لأنه أمر الروح النجس أن يخرج من الإنسان. لأنه منذ زمان كثير كان يخطفه, وقد ربط بسلاسل وقيود محروسا, وكان يقطع الربط ويساق من الشيطان إلى البراري.","8:30":"فسأله يسوع قائلا: «ما اسمك؟» فقال: «لجئون». لأن شياطين كثيرة دخلت فيه.","8:31":"وطلب إليه أن لا يأمرهم بالذهاب إلى الهاوية.","8:32":"وكان هناك قطيع خنازير كثيرة ترعى في الجبل, فطلبوا إليه أن يأذن لهم بالدخول فيها, فأذن لهم.","8:33":"فخرجت الشياطين من الإنسان ودخلت في الخنازير, فاندفع القطيع من على الجرف إلى البحيرة واختنق.","8:34":"فلما رأى الرعاة ما كان هربوا وذهبوا وأخبروا في المدينة وفي الضياع","8:35":"فخرجوا ليروا ما جرى. وجاءوا إلى يسوع فوجدوا الإنسان الذي كانت الشياطين قد خرجت منه لابسا وعاقلا, جالسا عند قدمي يسوع, فخافوا.","8:36":"فأخبرهم أيضا الذين رأوا كيف خلص المجنون.","8:37":"فطلب إليه كل جمهور كورة الجدريين أن يذهب عنهم, لأنه اعتراهم خوف عظيم. فدخل السفينة ورجع.","8:38":"أما الرجل الذي خرجت منه الشياطين فطلب إليه أن يكون معه, ولكن يسوع صرفه قائلا:","8:39":"«ارجع إلى بيتك وحدث بكم صنع الله بك». فمضى وهو ينادي في المدينة كلها بكم صنع به يسوع.","8:40":"ولما رجع يسوع قبله الجمع لأنهم كانوا جميعهم ينتظرونه.","8:41":"وإذا رجل اسمه يايرس قد جاء, - وكان رئيس المجمع, - فوقع عند قدمي يسوع وطلب إليه أن يدخل بيته","8:42":"لأنه كان له بنت وحيدة لها نحو اثنتي عشرة سنة, وكانت في حال الموت. ففيما هو منطلق زحمته الجموع.","8:43":"وامرأة بنزف دم منذ اثنتي عشرة سنة, وقد أنفقت كل معيشتها للأطباء, ولم تقدر أن تشفى من أحد","8:44":"جاءت من ورائه ولمست هدب ثوبه. ففي الحال وقف نزف دمها.","8:45":"فقال يسوع: «من الذي لمسني!» وإذ كان الجميع ينكرون, قال بطرس والذين معه: «يا معلم الجموع يضيقون عليك ويزحمونك, وتقول من الذي لمسني!»","8:46":"فقال يسوع: «قد لمسني واحد, لأني علمت أن قوة قد خرجت مني».","8:47":"فلما رأت المرأة أنها لم تختف, جاءت مرتعدة وخرت له, وأخبرته قدام جميع الشعب لأي سبب لمسته, وكيف برئت في الحال.","8:48":"فقال لها: «ثقي يا ابنة. إيمانك قد شفاك. اذهبي بسلام».","8:49":"وبينما هو يتكلم, جاء واحد من دار رئيس المجمع قائلا له: «قد ماتت ابنتك. لا تتعب المعلم».","8:50":"فسمع يسوع وأجابه قائلا: «لا تخف. آمن فقط فهي تشفى».","8:51":"فلما جاء إلى البيت لم يدع أحدا يدخل إلا بطرس ويعقوب ويوحنا, وأبا الصبية وأمها.","8:52":"وكان الجميع يبكون عليها ويلطمون. فقال: «لا تبكوا. لم تمت لكنها نائمة».","8:53":"فضحكوا عليه, عارفين أنها ماتت.","8:54":"فأخرج الجميع خارجا, وأمسك بيدها ونادى قائلا: «يا صبية, قومي».","8:55":"فرجعت روحها وقامت في الحال. فأمر أن تعطى لتأكل.","8:56":"فبهت والداها. فأوصاهما أن لا يقولا لأحد عما كان.","9:1":"ودعا تلاميذه الاثني عشر, وأعطاهم قوة وسلطانا على جميع الشياطين وشفاء أمراض","9:2":"وأرسلهم ليكرزوا بملكوت الله ويشفوا المرضى.","9:3":"وقال لهم: «لا تحملوا شيئا للطريق لا عصا ولا مزودا ولا خبزا ولا فضة, ولا يكون للواحد ثوبان.","9:4":"وأي بيت دخلتموه فهناك أقيموا, ومن هناك اخرجوا.","9:5":"وكل من لا يقبلكم فاخرجوا من تلك المدينة, وانفضوا الغبار أيضا عن أرجلكم شهادة عليهم».","9:6":"فلما خرجوا كانوا يجتازون في كل قرية يبشرون ويشفون في كل موضع.","9:7":"فسمع هيرودس رئيس الربع بجميع ما كان منه, وارتاب, لأن قوما كانوا يقولون: «إن يوحنا قد قام من الأموات».","9:8":"وقوما: «إن إيليا ظهر». وآخرين: «إن نبيا من القدماء قام».","9:9":"فقال هيرودس: «يوحنا أنا قطعت رأسه. فمن هو هذا الذي أسمع عنه مثل هذا!» وكان يطلب أن يراه.","9:10":"ولما رجع الرسل أخبروه بجميع ما فعلوا, فأخذهم وانصرف منفردا إلى موضع خلاء لمدينة تسمى بيت صيدا.","9:11":"فالجموع إذ علموا تبعوه, فقبلهم وكلمهم عن ملكوت الله, والمحتاجون إلى الشفاء شفاهم.","9:12":"فابتدأ النهار يميل. فتقدم الاثنا عشر وقالوا له: «اصرف الجمع ليذهبوا إلى القرى والضياع حوالينا فيبيتوا ويجدوا طعاما, لأننا ههنا في موضع خلاء».","9:13":"فقال لهم: «أعطوهم أنتم ليأكلوا». فقالوا: «ليس عندنا أكثر من خمسة أرغفة وسمكتين, إلا أن نذهب ونبتاع طعاما لهذا الشعب كله».","9:14":"لأنهم كانوا نحو خمسة آلاف رجل. فقال لتلاميذه: «أتكئوهم فرقا خمسين خمسين».","9:15":"ففعلوا هكذا, وأتكأوا الجميع.","9:16":"فأخذ الأرغفة الخمسة والسمكتين, ورفع نظره نحو السماء وباركهن, ثم كسر وأعطى التلاميذ ليقدموا للجمع.","9:17":"فأكلوا وشبعوا جميعا. ثم رفع ما فضل عنهم من الكسر: اثنتا عشرة قفة.","9:18":"وفيما هو يصلي على انفراد كان التلاميذ معه. فسألهم قائلا: «من تقول الجموع إني أنا؟»","9:19":"فأجابوا وقالوا: «يوحنا المعمدان. وآخرون إيليا. وآخرون إن نبيا من القدماء قام».","9:20":"فقال لهم: «وأنتم, من تقولون إني أنا؟» فأجاب بطرس وقال: «مسيح الله».","9:21":"فانتهرهم وأوصى أن لا يقولوا ذلك لأحد","9:22":"قائلا: «إنه ينبغي أن ابن الإنسان يتألم كثيرا, ويرفض من الشيوخ ورؤساء الكهنة والكتبة, ويقتل, وفي اليوم الثالث يقوم».","9:23":"وقال للجميع: «إن أراد أحد أن يأتي ورائي, فلينكر نفسه ويحمل صليبه كل يوم, ويتبعني.","9:24":"فإن من أراد أن يخلص نفسه يهلكها, ومن يهلك نفسه من أجلي فهذا يخلصها.","9:25":"لأنه ماذا ينتفع الإنسان لو ربح العالم كله, وأهلك نفسه أو خسرها؟","9:26":"لأن من استحى بي وبكلامي, فبهذا يستحي ابن الإنسان متى جاء بمجده ومجد الآب والملائكة القديسين.","9:27":"حقا أقول لكم: إن من القيام ههنا قوما لا يذوقون الموت حتى يروا ملكوت الله».","9:28":"وبعد هذا الكلام بنحو ثمانية أيام, أخذ بطرس ويوحنا ويعقوب وصعد إلى جبل ليصلي.","9:29":"وفيما هو يصلي صارت هيئة وجهه متغيرة, ولباسه مبيضا لامعا.","9:30":"وإذا رجلان يتكلمان معه, وهما موسى وإيليا","9:31":"اللذان ظهرا بمجد, وتكلما عن خروجه الذي كان عتيدا أن يكمله في أورشليم.","9:32":"وأما بطرس واللذان معه فكانوا قد تثقلوا بالنوم. فلما استيقظوا رأوا مجده, والرجلين الواقفين معه.","9:33":"وفيما هما يفارقانه قال بطرس ليسوع: «يا معلم جيد أن نكون ههنا. فلنصنع ثلاث مظال: لك واحدة, ولموسى واحدة, ولإيليا واحدة». وهو لا يعلم ما يقول.","9:34":"وفيما هو يقول ذلك كانت سحابة فظللتهم. فخافوا عندما دخلوا في السحابة.","9:35":"وصار صوت من السحابة قائلا: «هذا هو ابني الحبيب. له اسمعوا».","9:36":"ولما كان الصوت وجد يسوع وحده, وأما هم فسكتوا ولم يخبروا أحدا في تلك الأيام بشيء مما أبصروه.","9:37":"وفي اليوم التالي إذ نزلوا من الجبل, استقبله جمع كثير.","9:38":"وإذا رجل من الجمع صرخ قائلا: «يا معلم, أطلب إليك. انظر إلى ابني, فإنه وحيد لي.","9:39":"وها روح يأخذه فيصرخ بغتة, فيصرعه مزبدا, وبالجهد يفارقه مرضضا إياه.","9:40":"وطلبت من تلاميذك أن يخرجوه فلم يقدروا».","9:41":"فأجاب يسوع وقال: «أيها الجيل غير المؤمن والملتوي إلى متى أكون معكم وأحتملكم؟ قدم ابنك إلى هنا».","9:42":"وبينما هو آت مزقه الشيطان وصرعه, فانتهر يسوع الروح النجس, وشفى الصبي وسلمه إلى أبيه.","9:43":"فبهت الجميع من عظمة الله. وإذ كان الجميع يتعجبون من كل ما فعل يسوع, قال لتلاميذه:","9:44":"«ضعوا أنتم هذا الكلام في آذانكم: إن ابن الإنسان سوف يسلم إلى أيدي الناس».","9:45":"وأما هم فلم يفهموا هذا القول, وكان مخفى عنهم لكي لا يفهموه, وخافوا أن يسألوه عن هذا القول.","9:46":"وداخلهم فكر: من عسى أن يكون أعظم فيهم؟","9:47":"فعلم يسوع فكر قلبهم, وأخذ ولدا وأقامه عنده","9:48":"وقال لهم: «من قبل هذا الولد باسمي يقبلني, ومن قبلني يقبل الذي أرسلني, لأن الأصغر فيكم جميعا هو يكون عظيما»","9:49":"فأجاب يوحنا وقال: «يا معلم, رأينا واحدا يخرج الشياطين باسمك فمنعناه, لأنه ليس يتبع معنا».","9:50":"فقال له يسوع: «لا تمنعوه, لأن من ليس علينا فهو معنا».","9:51":"وحين تمت الأيام لارتفاعه ثبت وجهه لينطلق إلى أورشليم","9:52":"وأرسل أمام وجهه رسلا, فذهبوا ودخلوا قرية للسامريين حتى يعدوا له.","9:53":"فلم يقبلوه لأن وجهه كان متجها نحو أورشليم.","9:54":"فلما رأى ذلك تلميذاه يعقوب ويوحنا, قالا: «يا رب أتريد أن نقول أن تنزل نار من السماء فتفنيهم, كما فعل إيليا أيضا؟»","9:55":"فالتفت وانتهرهما وقال: «لستما تعلمان من أي روح أنتما!","9:56":"لأن ابن الإنسان لم يأت ليهلك أنفس الناس, بل ليخلص». فمضوا إلى قرية أخرى.","9:57":"وفيما هم سائرون في الطريق قال له واحد: «يا سيد, أتبعك أينما تمضي».","9:58":"فقال له يسوع: «للثعالب أوجرة, ولطيور السماء أوكار, وأما ابن الإنسان فليس له أين يسند رأسه».","9:59":"وقال لآخر: «اتبعني». فقال: «يا سيد, ائذن لي أن أمضي أولا وأدفن أبي».","9:60":"فقال له يسوع: «دع الموتى يدفنون موتاهم, وأما أنت فاذهب وناد بملكوت الله».","9:61":"وقال آخر أيضا: «أتبعك يا سيد, ولكن ائذن لي أولا أن أودع الذين في بيتي».","9:62":"فقال له يسوع: «ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله».","10:1":"وبعد ذلك عين الرب سبعين آخرين أيضا, وأرسلهم اثنين اثنين أمام وجهه إلى كل مدينة وموضع حيث كان هو مزمعا أن يأتي.","10:2":"فقال لهم: «إن الحصاد كثير, ولكن الفعلة قليلون. فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده.","10:3":"اذهبوا. ها أنا أرسلكم مثل حملان بين ذئاب.","10:4":"لا تحملوا كيسا ولا مزودا ولا أحذية, ولا تسلموا على أحد في الطريق.","10:5":"وأي بيت دخلتموه فقولوا أولا: سلام لهذا البيت.","10:6":"فإن كان هناك ابن السلام يحل سلامكم عليه, وإلا فيرجع إليكم.","10:7":"وأقيموا في ذلك البيت آكلين وشاربين مما عندهم, لأن الفاعل مستحق أجرته. لا تنتقلوا من بيت إلى بيت.","10:8":"وأية مدينة دخلتموها وقبلوكم, فكلوا مما يقدم لكم","10:9":"واشفوا المرضى الذين فيها, وقولوا لهم: قد اقترب منكم ملكوت الله","10:10":"وأية مدينة دخلتموها ولم يقبلوكم, فاخرجوا إلى شوارعها وقولوا:","10:11":"حتى الغبار الذي لصق بنا من مدينتكم ننفضه لكم. ولكن اعلموا هذا أنه قد اقترب منكم ملكوت الله.","10:12":"وأقول لكم إنه يكون لسدوم في ذلك اليوم حالة أكثر احتمالا مما لتلك المدينة.","10:13":"«ويل لك يا كورزين! ويل لك يا بيت صيدا! لأنه لو صنعت في صور وصيداء القوات المصنوعة فيكما, لتابتا قديما جالستين في المسوح والرماد.","10:14":"ولكن صور وصيداء يكون لهما في الدين حالة أكثر احتمالا مما لكما.","10:15":"وأنت يا كفرناحوم المرتفعة إلى السماء ستهبطين إلى الهاوية.","10:16":"الذي يسمع منكم يسمع مني, والذي يرذلكم يرذلني, والذي يرذلني يرذل الذي أرسلني».","10:17":"فرجع السبعون بفرح قائلين: «يا رب حتى الشياطين تخضع لنا باسمك».","10:18":"فقال لهم: «رأيت الشيطان ساقطا مثل البرق من السماء.","10:19":"ها أنا أعطيكم سلطانا لتدوسوا الحيات والعقارب وكل قوة العدو, ولا يضركم شيء.","10:20":"ولكن لا تفرحوا بهذا أن الأرواح تخضع لكم, بل افرحوا بالحري أن أسماءكم كتبت في السماوات».","10:21":"وفي تلك الساعة تهلل يسوع بالروح وقال: «أحمدك أيها الآب, رب السماء والأرض, لأنك أخفيت هذه عن الحكماء والفهماء وأعلنتها للأطفال. نعم أيها الآب, لأن هكذا صارت المسرة أمامك».","10:22":"والتفت إلى تلاميذه وقال: «كل شيء قد دفع إلي من أبي. وليس أحد يعرف من هو الابن إلا الآب, ولا من هو الآب إلا الابن, ومن أراد الابن أن يعلن له».","10:23":"والتفت إلى تلاميذه على انفراد وقال: «طوبى للعيون التي تنظر ما تنظرونه","10:24":"لأني أقول لكم: إن أنبياء كثيرين وملوكا أرادوا أن ينظروا ما أنتم تنظرون ولم ينظروا, وأن يسمعوا ما أنتم تسمعون ولم يسمعوا».","10:25":"وإذا ناموسي قام يجربه قائلا: «يا معلم, ماذا أعمل لأرث الحياة الأبدية؟»","10:26":"فقال له: «ما هو مكتوب في الناموس. كيف تقرأ؟»","10:27":"فأجاب وقال: «تحب الرب إلهك من كل قلبك, ومن كل نفسك, ومن كل قدرتك, ومن كل فكرك, وقريبك مثل نفسك».","10:28":"فقال له: «بالصواب أجبت. افعل هذا فتحيا».","10:29":"وأما هو فإذ أراد أن يبرر نفسه, قال ليسوع: «ومن هو قريبي؟»","10:30":"فأجاب يسوع وقال: «إنسان كان نازلا من أورشليم إلى أريحا, فوقع بين لصوص, فعروه وجرحوه, ومضوا وتركوه بين حي وميت.","10:31":"فعرض أن كاهنا نزل في تلك الطريق, فرآه وجاز مقابله.","10:32":"وكذلك لاوي أيضا, إذ صار عند المكان جاء ونظر وجاز مقابله.","10:33":"ولكن سامريا مسافرا جاء إليه, ولما رآه تحنن","10:34":"فتقدم وضمد جراحاته, وصب عليها زيتا وخمرا, وأركبه على دابته, وأتى به إلى فندق واعتنى به.","10:35":"وفي الغد لما مضى أخرج دينارين وأعطاهما لصاحب الفندق, وقال له: اعتن به, ومهما أنفقت أكثر فعند رجوعي أوفيك.","10:36":"فأي هؤلاء الثلاثة ترى صار قريبا للذي وقع بين اللصوص؟»","10:37":"فقال: «الذي صنع معه الرحمة». فقال له يسوع: «اذهب أنت أيضا واصنع هكذا».","10:38":"وفيما هم سائرون دخل قرية, فقبلته امرأة اسمها مرثا في بيتها.","10:39":"وكانت لهذه أخت تدعى مريم, التي جلست عند قدمي يسوع وكانت تسمع كلامه.","10:40":"وأما مرثا فكانت مرتبكة في خدمة كثيرة فوقفت وقالت: «يا رب أما تبالي بأن أختي قد تركتني أخدم وحدي؟ فقل لها أن تعينني!»","10:41":"فأجاب يسوع وقال لها: «مرثا, مرثا, أنت تهتمين وتضطربين لأجل أمور كثيرة","10:42":"ولكن الحاجة إلى واحد. فاختارت مريم النصيب الصالح الذي لن ينزع منها».","11:1":"وإذ كان يصلي في موضع, لما فرغ, قال واحد من تلاميذه: «يا رب علمنا أن نصلي كما علم يوحنا أيضا تلاميذه».","11:2":"فقال لهم: «متى صليتم فقولوا: أبانا الذي في السماوات, ليتقدس اسمك, ليأت ملكوتك, لتكن مشيئتك كما في السماء كذلك على الأرض.","11:3":"خبزنا كفافنا أعطنا كل يوم","11:4":"واغفر لنا خطايانا لأننا نحن أيضا نغفر لكل من يذنب إلينا, ولا تدخلنا في تجربة لكن نجنا من الشرير».","11:5":"ثم قال لهم: «من منكم يكون له صديق, ويمضي إليه نصف الليل, ويقول له: يا صديق أقرضني ثلاثة أرغفة","11:6":"لأن صديقا لي جاءني من سفر, وليس لي ما أقدم له.","11:7":"فيجيب ذلك من داخل ويقول: لا تزعجني! الباب مغلق الآن, وأولادي معي في الفراش. لا أقدر أن أقوم وأعطيك.","11:8":"أقول لكم: وإن كان لا يقوم ويعطيه لكونه صديقه, فإنه من أجل لجاجته يقوم ويعطيه قدر ما يحتاج.","11:9":"وأنا أقول لكم: اسألوا تعطوا. اطلبوا تجدوا. اقرعوا يفتح لكم.","11:10":"لأن كل من يسأل يأخذ, ومن يطلب يجد, ومن يقرع يفتح له.","11:11":"فمن منكم, وهو أب, يسأله ابنه خبزا, أفيعطيه حجرا؟ أو سمكة, أفيعطيه حية بدل السمكة؟","11:12":"أو إذا سأله بيضة, أفيعطيه عقربا؟","11:13":"فإن كنتم وأنتم أشرار تعرفون أن تعطوا أولادكم عطايا جيدة, فكم بالحري الآب الذي من السماء, يعطي الروح القدس للذين يسألونه».","11:14":"وكان يخرج شيطانا, وكان ذلك أخرس. فلما أخرج الشيطان تكلم الأخرس, فتعجب الجموع.","11:15":"وأما قوم منهم فقالوا: «ببعلزبول رئيس الشياطين يخرج الشياطين».","11:16":"وآخرون طلبوا منه آية من السماء يجربونه.","11:17":"فعلم أفكارهم, وقال لهم: «كل مملكة منقسمة على ذاتها تخرب, وبيت منقسم على بيت يسقط.","11:18":"فإن كان الشيطان أيضا ينقسم على ذاته, فكيف تثبت مملكته؟ لأنكم تقولون: إني ببعلزبول أخرج الشياطين.","11:19":"فإن كنت أنا ببعلزبول أخرج الشياطين, فأبناؤكم بمن يخرجون؟ لذلك هم يكونون قضاتكم.","11:20":"ولكن إن كنت بإصبع الله أخرج الشياطين, فقد أقبل عليكم ملكوت الله.","11:21":"حينما يحفظ القوي داره متسلحا, تكون أمواله في أمان.","11:22":"ولكن متى جاء من هو أقوى منه فإنه يغلبه, وينزع سلاحه الكامل الذي اتكل عليه, ويوزع غنائمه.","11:23":"من ليس معي فهو علي, ومن لا يجمع معي فهو يفرق.","11:24":"متى خرج الروح النجس من الإنسان, يجتاز في أماكن ليس فيها ماء يطلب راحة, وإذ لا يجد يقول: أرجع إلى بيتي الذي خرجت منه","11:25":"فيأتي ويجده مكنوسا مزينا.","11:26":"ثم يذهب ويأخذ سبعة أرواح أخر أشر منه, فتدخل وتسكن هناك, فتصير أواخر ذلك الإنسان أشر من أوائله!»","11:27":"وفيما هو يتكلم بهذا, رفعت امرأة صوتها من الجمع وقالت له: «طوبى للبطن الذي حملك والثديين اللذين رضعتهما».","11:28":"أما هو فقال: «بل طوبى للذين يسمعون كلام الله ويحفظونه».","11:29":"وفيما كان الجموع مزدحمين, ابتدأ يقول: «هذا الجيل شرير. يطلب آية, ولا تعطى له آية إلا آية يونان النبي.","11:30":"لأنه كما كان يونان آية لأهل نينوى, كذلك يكون ابن الإنسان أيضا لهذا الجيل.","11:31":"ملكة التيمن ستقوم في الدين مع رجال هذا الجيل وتدينهم, لأنها أتت من أقاصي الأرض لتسمع حكمة سليمان, وهوذا أعظم من سليمان ههنا.","11:32":"رجال نينوى سيقومون في الدين مع هذا الجيل ويدينونه, لأنهم تابوا بمناداة يونان, وهوذا أعظم من يونان ههنا!","11:33":"«ليس أحد يوقد سراجا ويضعه في خفية, ولا تحت المكيال, بل على المنارة, لكي ينظر الداخلون النور.","11:34":"سراج الجسد هو العين, فمتى كانت عينك بسيطة فجسدك كله يكون نيرا, ومتى كانت شريرة فجسدك يكون مظلما.","11:35":"انظر إذا لئلا يكون النور الذي فيك ظلمة.","11:36":"فإن كان جسدك كله نيرا ليس فيه جزء مظلم, يكون نيرا كله, كما حينما يضيء لك السراج بلمعانه».","11:37":"وفيما هو يتكلم سأله فريسي أن يتغدى عنده, فدخل واتكأ.","11:38":"وأما الفريسي فلما رأى ذلك تعجب أنه لم يغتسل أولا قبل الغداء.","11:39":"فقال له الرب: «أنتم الآن أيها الفريسيون تنقون خارج الكأس والقصعة, وأما باطنكم فمملوء اختطافا وخبثا.","11:40":"يا أغبياء, أليس الذي صنع الخارج صنع الداخل أيضا؟","11:41":"بل أعطوا ما عندكم صدقة, فهوذا كل شيء يكون نقيا لكم.","11:42":"ولكن ويل لكم أيها الفريسيون لأنكم تعشرون النعنع والسذاب وكل بقل, وتتجاوزون عن الحق ومحبة الله. كان ينبغي أن تعملوا هذه ولا تتركوا تلك!","11:43":"ويل لكم أيها الفريسيون لأنكم تحبون المجلس الأول في المجامع, والتحيات في الأسواق.","11:44":"ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم مثل القبور المختفية, والذين يمشون عليها لا يعلمون!».","11:45":"فأجاب واحد من الناموسيين وقال له: «يا معلم حين تقول هذا تشتمنا نحن أيضا».","11:46":"فقال: «وويل لكم أنتم أيها الناموسيون لأنكم تحملون الناس أحمالا عسرة الحمل وأنتم لا تمسون الأحمال بإحدى أصابعكم.","11:47":"ويل لكم لأنكم تبنون قبور الأنبياء, وآباؤكم قتلوهم.","11:48":"إذا تشهدون وترضون بأعمال آبائكم, لأنهم هم قتلوهم وأنتم تبنون قبورهم.","11:49":"لذلك أيضا قالت حكمة الله: إني أرسل إليهم أنبياء ورسلا, فيقتلون منهم ويطردون -","11:50":"لكي يطلب من هذا الجيل دم جميع الأنبياء المهرق منذ إنشاء العالم","11:51":"من دم هابيل إلى دم زكريا الذي أهلك بين المذبح والبيت. نعم, أقول لكم: إنه يطلب من هذا الجيل!","11:52":"ويل لكم أيها الناموسيون لأنكم أخذتم مفتاح المعرفة. ما دخلتم أنتم, والداخلون منعتموهم».","11:53":"وفيما هو يكلمهم بهذا, ابتدأ الكتبة والفريسيون يحنقون جدا, ويصادرونه على أمور كثيرة","14:29":"لئلا يضع الأساس ولا يقدر أن يكمل, فيبتدئ جميع الناظرين يهزأون به","14:30":"قائلين: هذا الإنسان ابتدأ يبني ولم يقدر أن يكمل.","14:31":"وأي ملك إن ذهب لمقاتلة ملك آخر في حرب, لا يجلس أولا ويتشاور: هل يستطيع أن يلاقي بعشرة آلاف الذي يأتي عليه بعشرين ألفا؟","14:32":"وإلا فما دام ذلك بعيدا, يرسل سفارة ويسأل ما هو للصلح.","14:33":"فكذلك كل واحد منكم لا يترك جميع أمواله, لا يقدر أن يكون لي تلميذا.","14:34":"الملح جيد. ولكن إذا فسد الملح, فبماذا يصلح؟","14:35":"لا يصلح لأرض ولا لمزبلة, فيطرحونه خارجا. من له أذنان للسمع, فليسمع!».","15:1":"وكان جميع العشارين والخطاة يدنون منه ليسمعوه.","15:2":"فتذمر الفريسيون والكتبة قائلين: «هذا يقبل خطاة ويأكل معهم».","15:3":"فكلمهم بهذا المثل قائلا:","15:4":"«أي إنسان منكم له مئة خروف, وأضاع واحدا منها, ألا يترك التسعة والتسعين في البرية, ويذهب لأجل الضال حتى يجده؟","15:5":"وإذا وجده يضعه على منكبيه فرحا","15:6":"ويأتي إلى بيته ويدعو الأصدقاء والجيران قائلا لهم: افرحوا معي, لأني وجدت خروفي الضال.","15:7":"أقول لكم إنه هكذا يكون فرح في السماء بخاطئ واحد يتوب أكثر من تسعة وتسعين بارا لا يحتاجون إلى توبة».","15:8":"«أو أية امرأة لها عشرة دراهم, إن أضاعت درهما واحدا, ألا توقد سراجا وتكنس البيت وتفتش باجتهاد حتى تجده؟","15:9":"وإذا وجدته تدعو الصديقات والجارات قائلة: افرحن معي لأني وجدت الدرهم الذي أضعته.","15:10":"هكذا, أقول لكم يكون فرح قدام ملائكة الله بخاطئ واحد يتوب».","15:11":"وقال: «إنسان كان له ابنان.","15:12":"فقال أصغرهما لأبيه: يا أبي أعطني القسم الذي يصيبني من المال. فقسم لهما معيشته.","15:13":"وبعد أيام ليست بكثيرة جمع الابن الأصغر كل شيء وسافر إلى كورة بعيدة, وهناك بذر ماله بعيش مسرف.","15:14":"فلما أنفق كل شيء, حدث جوع شديد في تلك الكورة, فابتدأ يحتاج.","15:15":"فمضى والتصق بواحد من أهل تلك الكورة, فأرسله إلى حقوله ليرعى خنازير.","15:16":"وكان يشتهي أن يملأ بطنه من الخرنوب الذي كانت الخنازير تأكله, فلم يعطه أحد.","15:17":"فرجع إلى نفسه وقال: كم من أجير لأبي يفضل عنه الخبز وأنا أهلك جوعا!","15:18":"أقوم وأذهب إلى أبي وأقول له: يا أبي, أخطأت إلى السماء وقدامك","15:19":"ولست مستحقا بعد أن أدعى لك ابنا. اجعلني كأحد أجراك.","15:20":"فقام وجاء إلى أبيه. وإذ كان لم يزل بعيدا رآه أبوه, فتحنن وركض ووقع على عنقه وقبله.","15:21":"فقال له الابن: يا أبي, أخطأت إلى السماء وقدامك, ولست مستحقا بعد أن أدعى لك ابنا.","15:22":"فقال الأب لعبيده: أخرجوا الحلة الأولى وألبسوه, واجعلوا خاتما في يده, وحذاء في رجليه","15:23":"وقدموا العجل المسمن واذبحوه فنأكل ونفرح","15:24":"لأن ابني هذا كان ميتا فعاش, وكان ضالا فوجد. فابتدأوا يفرحون.","15:25":"وكان ابنه الأكبر في الحقل. فلما جاء وقرب من البيت, سمع صوت آلات طرب ورقصا","15:26":"فدعا واحدا من الغلمان وسأله: ما عسى أن يكون هذا؟","15:27":"فقال له: أخوك جاء فذبح أبوك العجل المسمن, لأنه قبله سالما.","15:28":"فغضب ولم يرد أن يدخل. فخرج أبوه يطلب إليه.","15:29":"فأجاب وقال لأبيه: ها أنا أخدمك سنين هذا عددها, وقط لم أتجاوز وصيتك, وجديا لم تعطني قط لأفرح مع أصدقائي.","15:30":"ولكن لما جاء ابنك هذا الذي أكل معيشتك مع الزواني, ذبحت له العجل المسمن.","15:31":"فقال له: يا بني أنت معي في كل حين, وكل ما لي فهو لك.","15:32":"ولكن كان ينبغي أن نفرح ونسر, لأن أخاك هذا كان ميتا فعاش, وكان ضالا فوجد».","16:1":"وقال أيضا لتلاميذه: «كان إنسان غني له وكيل, فوشي به إليه بأنه يبذر أمواله.","16:2":"فدعاه وقال له: ما هذا الذي أسمع عنك؟ أعط حساب وكالتك لأنك لا تقدر أن تكون وكيلا بعد.","16:3":"فقال الوكيل في نفسه: ماذا أفعل؟ لأن سيدي يأخذ مني الوكالة. لست أستطيع أن أنقب, وأستحي أن أستعطي.","16:4":"قد علمت ماذا أفعل, حتى إذا عزلت عن الوكالة يقبلوني في بيوتهم.","16:5":"فدعا كل واحد من مديوني سيده, وقال للأول: كم عليك لسيدي؟","16:6":"فقال: مئة بث زيت. فقال له: خذ صكك واجلس عاجلا واكتب خمسين.","16:7":"ثم قال لآخر: وأنت كم عليك؟ فقال: مئة كر قمح. فقال له: خذ صكك واكتب ثمانين.","16:8":"فمدح السيد وكيل الظلم إذ بحكمة فعل, لأن أبناء هذا الدهر أحكم من أبناء النور في جيلهم.","16:9":"وأنا أقول لكم: اصنعوا لكم أصدقاء بمال الظلم, حتى إذا فنيتم يقبلونكم في المظال الأبدية.","16:10":"الأمين في القليل أمين أيضا في الكثير, والظالم في القليل ظالم أيضا في الكثير.","16:11":"فإن لم تكونوا أمناء في مال الظلم, فمن يأتمنكم على الحق؟","16:12":"وإن لم تكونوا أمناء في ما هو للغير, فمن يعطيكم ما هو لكم؟","16:13":"لا يقدر خادم أن يخدم سيدين, لأنه إما أن يبغض الواحد ويحب الآخر, أو يلازم الواحد ويحتقر الآخر. لا تقدرون أن تخدموا الله والمال».","16:14":"وكان الفريسيون أيضا يسمعون هذا كله, وهم محبون للمال, فاستهزأوا به.","16:15":"فقال لهم: «أنتم الذين تبررون أنفسكم قدام الناس! ولكن الله يعرف قلوبكم. إن المستعلي عند الناس هو رجس قدام الله.","16:16":"«كان الناموس والأنبياء إلى يوحنا. ومن ذلك الوقت يبشر بملكوت الله, وكل واحد يغتصب نفسه إليه.","16:17":"ولكن زوال السماء والأرض أيسر من أن تسقط نقطة واحدة من الناموس.","16:18":"كل من يطلق امرأته ويتزوج بأخرى يزني, وكل من يتزوج بمطلقة من رجل يزني.","16:19":"«كان إنسان غني وكان يلبس الأرجوان والبز وهو يتنعم كل يوم مترفها.","16:20":"وكان مسكين اسمه لعازر, الذي طرح عند بابه مضروبا بالقروح","16:21":"ويشتهي أن يشبع من الفتات الساقط من مائدة الغني, بل كانت الكلاب تأتي وتلحس قروحه.","16:22":"فمات المسكين وحملته الملائكة إلى حضن إبراهيم. ومات الغني أيضا ودفن","16:23":"فرفع عينيه في الجحيم وهو في العذاب, ورأى إبراهيم من بعيد ولعازر في حضنه","16:24":"فنادى وقال: يا أبي إبراهيم, ارحمني, وأرسل لعازر ليبل طرف إصبعه بماء ويبرد لساني, لأني معذب في هذا اللهيب.","16:25":"فقال إبراهيم: يا ابني, اذكر أنك استوفيت خيراتك في حياتك, وكذلك لعازر البلايا. والآن هو يتعزى وأنت تتعذب.","16:26":"وفوق هذا كله, بيننا وبينكم هوة عظيمة قد أثبتت, حتى إن الذين يريدون العبور من ههنا إليكم لا يقدرون, ولا الذين من هناك يجتازون إلينا.","16:27":"فقال: أسألك إذا, يا أبت, أن ترسله إلى بيت أبي","16:28":"لأن لي خمسة إخوة, حتى يشهد لهم لكيلا يأتوا هم أيضا إلى موضع العذاب هذا.","16:29":"قال له إبراهيم: عندهم موسى والأنبياء. ليسمعوا منهم.","16:30":"فقال: لا, يا أبي إبراهيم. بل إذا مضى إليهم واحد من الأموات يتوبون.","16:31":"فقال له: إن كانوا لا يسمعون من موسى والأنبياء, ولا إن قام واحد من الأموات يصدقون».","17:1":"وقال لتلاميذه: «لا يمكن إلا أن تأتي العثرات, ولكن ويل للذي تأتي بواسطته!","17:2":"خير له لو طوق عنقه بحجر رحى وطرح في البحر, من أن يعثر أحد هؤلاء الصغار.","17:3":"احترزوا لأنفسكم. وإن أخطأ إليك أخوك فوبخه, وإن تاب فاغفر له.","17:4":"وإن أخطأ إليك سبع مرات في اليوم, ورجع إليك سبع مرات في اليوم قائلا: أنا تائب, فاغفر له».","17:5":"فقال الرسل للرب: «زد إيماننا».","17:6":"فقال الرب: «لو كان لكم إيمان مثل حبة خردل, لكنتم تقولون لهذه الجميزة انقلعي وانغرسي في البحر فتطيعكم.","17:7":"«ومن منكم له عبد يحرث أو يرعى, يقول له إذا دخل من الحقل: تقدم سريعا واتكئ.","17:8":"بل ألا يقول له: أعدد ما أتعشى به, وتمنطق واخدمني حتى آكل وأشرب, وبعد ذلك تأكل وتشرب أنت.","17:9":"فهل لذلك العبد فضل لأنه فعل ما أمر به؟ لا أظن.","17:10":"كذلك أنتم أيضا, متى فعلتم كل ما أمرتم به فقولوا: إننا عبيد بطالون. لأننا إنما عملنا ما كان يجب علينا».","17:11":"وفي ذهابه إلى أورشليم اجتاز في وسط السامرة والجليل.","17:12":"وفيما هو داخل إلى قرية استقبله عشرة رجال برص, فوقفوا من بعيد","17:13":"ورفعوا صوتا قائلين: «يا يسوع, يا معلم, ارحمنا».","17:14":"فنظر وقال لهم: «اذهبوا وأروا أنفسكم للكهنة». وفيما هم منطلقون طهروا.","17:15":"فواحد منهم لما رأى أنه شفي, رجع يمجد الله بصوت عظيم","17:16":"وخر على وجهه عند رجليه شاكرا له. وكان سامريا.","17:17":"فأجاب يسوع وقال: «أليس العشرة قد طهروا؟ فأين التسعة؟","17:18":"ألم يوجد من يرجع ليعطي مجدا لله غير هذا الغريب الجنس؟»","17:19":"ثم قال له: «قم وامض. إيمانك خلصك».","17:20":"ولما سأله الفريسيون: «متى يأتي ملكوت الله؟» أجابهم وقال: «لا يأتي ملكوت الله بمراقبة","17:21":"ولا يقولون: هوذا ههنا, أو: هوذا هناك لأن ها ملكوت الله داخلكم».","17:22":"وقال للتلاميذ: «ستأتي أيام فيها تشتهون أن تروا يوما واحدا من أيام ابن الإنسان ولا ترون.","17:23":"ويقولون لكم: هوذا ههنا أو: هوذا هناك. لا تذهبوا ولا تتبعوا","17:24":"لأنه كما أن البرق الذي يبرق من ناحية تحت السماء يضيء إلى ناحية تحت السماء, كذلك يكون أيضا ابن الإنسان في يومه.","17:25":"ولكن ينبغي أولا أن يتألم كثيرا ويرفض من هذا الجيل.","17:26":"وكما كان في أيام نوح كذلك يكون أيضا في أيام ابن الإنسان.","17:27":"كانوا يأكلون ويشربون, ويزوجون ويتزوجون, إلى اليوم الذي فيه دخل نوح الفلك, وجاء الطوفان وأهلك الجميع.","17:28":"كذلك أيضا كما كان في أيام لوط كانوا يأكلون ويشربون, ويشترون ويبيعون, ويغرسون ويبنون.","17:29":"ولكن اليوم الذي فيه خرج لوط من سدوم, أمطر نارا وكبريتا من السماء فأهلك الجميع.","17:30":"هكذا يكون في اليوم الذي فيه يظهر ابن الإنسان.","17:31":"في ذلك اليوم من كان على السطح وأمتعته في البيت فلا ينزل ليأخذها, والذي في الحقل كذلك لا يرجع إلى الوراء.","17:32":"اذكروا امرأة لوط!","17:33":"من طلب أن يخلص نفسه يهلكها, ومن أهلكها يحييها.","17:34":"أقول لكم: إنه في تلك الليلة يكون اثنان على فراش واحد فيؤخذ الواحد ويترك الآخر.","17:35":"تكون اثنتان تطحنان معا, فتؤخذ الواحدة وتترك الأخرى.","17:36":"يكون اثنان في الحقل, فيؤخذ الواحد ويترك الآخر».","17:37":"فأجابوا وقالوا له: «أين يا رب؟» فقال لهم: «حيث تكون الجثة هناك تجتمع النسور».","18:1":"وقال لهم أيضا مثلا في أنه ينبغي أن يصلى كل حين ولا يمل:","18:2":"«قائلا كان في مدينة قاض لا يخاف الله ولا يهاب إنسانا.","18:3":"وكان في تلك المدينة أرملة. وكانت تأتي إليه قائلة: أنصفني من خصمي.","18:4":"وكان لا يشاء إلى زمان. ولكن بعد ذلك قال في نفسه: وإن كنت لا أخاف الله ولا أهاب إنسانا","18:5":"فإني لأجل أن هذه الأرملة تزعجني, أنصفها, لئلا تأتي دائما فتقمعني».","18:6":"وقال الرب: «اسمعوا ما يقول قاضي الظلم.","18:7":"أفلا ينصف الله مختاريه, الصارخين إليه نهارا وليلا, وهو متمهل عليهم؟","18:8":"أقول لكم إنه ينصفهم سريعا! ولكن متى جاء ابن الإنسان, ألعله يجد الإيمان على الأرض؟».","18:9":"وقال لقوم واثقين بأنفسهم أنهم أبرار, ويحتقرون الآخرين هذا المثل:","18:10":"«إنسانان صعدا إلى الهيكل ليصليا, واحد فريسي والآخر عشار.","18:11":"أما الفريسي فوقف يصلي في نفسه هكذا: اللهم أنا أشكرك أني لست مثل باقي الناس الخاطفين الظالمين الزناة, ولا مثل هذا العشار.","18:12":"أصوم مرتين في الأسبوع, وأعشر كل ما أقتنيه.","18:13":"وأما العشار فوقف من بعيد, لا يشاء أن يرفع عينيه نحو السماء, بل قرع على صدره قائلا: اللهم ارحمني, أنا الخاطئ.","18:14":"أقول لكم إن هذا نزل إلى بيته مبررا دون ذاك, لأن كل من يرفع نفسه يتضع, ومن يضع نفسه يرتفع».","18:15":"فقدموا إليه الأطفال أيضا ليلمسهم, فلما رآهم التلاميذ انتهروهم.","18:16":"أما يسوع فدعاهم وقال: «دعوا الأولاد يأتون إلي ولا تمنعوهم, لأن لمثل هؤلاء ملكوت الله.","18:17":"الحق أقول لكم: من لا يقبل ملكوت الله مثل ولد فلن يدخله».","18:18":"وسأله رئيس قائلا: «أيها المعلم الصالح, ماذا أعمل لأرث الحياة الأبدية؟»","18:19":"فقال له يسوع: «لماذا تدعوني صالحا؟ ليس أحد صالحا إلا واحد وهو الله.","18:20":"أنت تعرف الوصايا: لا تزن. لا تقتل. لا تسرق. لا تشهد بالزور. أكرم أباك وأمك».","18:21":"فقال: «هذه كلها حفظتها منذ حداثتي».","18:22":"فلما سمع يسوع ذلك قال له: «يعوزك أيضا شيء. بع كل ما لك ووزع على الفقراء, فيكون لك كنز في السماء, وتعال اتبعني».","18:23":"فلما سمع ذلك حزن, لأنه كان غنيا جدا.","18:24":"فلما رآه يسوع قد حزن, قال: «ما أعسر دخول ذوي الأموال إلى ملكوت الله!","18:25":"لأن دخول جمل من ثقب إبرة أيسر من أن يدخل غني إلى ملكوت الله!».","18:26":"فقال الذين سمعوا: «فمن يستطيع أن يخلص؟»","18:27":"فقال: «غير المستطاع عند الناس مستطاع عند الله».","18:28":"فقال بطرس: «ها نحن قد تركنا كل شيء وتبعناك».","18:29":"فقال لهم: «الحق أقول لكم: إن ليس أحد ترك بيتا أو والدين أو إخوة أو امرأة أو أولادا من أجل ملكوت الله","18:30":"إلا ويأخذ في هذا الزمان أضعافا كثيرة, وفي الدهر الآتي الحياة الأبدية».","18:31":"وأخذ الاثني عشر وقال لهم: «ها نحن صاعدون إلى أورشليم, وسيتم كل ما هو مكتوب بالأنبياء عن ابن الإنسان","18:32":"لأنه يسلم إلى الأمم, ويستهزأ به, ويشتم ويتفل عليه","18:33":"ويجلدونه, ويقتلونه, وفي اليوم الثالث يقوم».","18:34":"وأما هم فلم يفهموا من ذلك شيئا, وكان هذا الأمر مخفى عنهم, ولم يعلموا ما قيل.","18:35":"ولما اقترب من أريحا كان أعمى جالسا على الطريق يستعطي.","18:36":"فلما سمع الجمع مجتازا سأل: «ما عسى أن يكون هذا؟»","18:37":"فأخبروه أن يسوع الناصري مجتاز.","18:38":"فصرخ قائلا: «يا يسوع ابن داود ارحمني!».","18:39":"فانتهره المتقدمون ليسكت, أما هو فصرخ أكثر كثيرا: «يا ابن داود, ارحمني».","18:40":"فوقف يسوع وأمر أن يقدم إليه. ولما اقترب سأله:","18:41":"قائلا: «ماذا تريد أن أفعل بك؟» فقال: «يا سيد أن أبصر».","18:42":"فقال له يسوع: «أبصر. إيمانك قد شفاك».","18:43":"وفي الحال أبصر, وتبعه وهو يمجد الله. وجميع الشعب إذ رأوا سبحوا الله.","19:1":"ثم دخل واجتاز في أريحا.","19:2":"وإذا رجل اسمه زكا, وهو رئيس للعشارين وكان غنيا","19:3":"وطلب أن يرى يسوع من هو, ولم يقدر من الجمع, لأنه كان قصير القامة.","19:4":"فركض متقدما وصعد إلى جميزة لكي يراه, لأنه كان مزمعا أن يمر من هناك.","19:5":"فلما جاء يسوع إلى المكان, نظر إلى فوق فرآه, وقال له: «يا زكا, أسرع وانزل, لأنه ينبغي أن أمكث اليوم في بيتك».","19:6":"فأسرع ونزل وقبله فرحا.","19:7":"فلما رأى الجميع ذلك تذمروا قائلين: «إنه دخل ليبيت عند رجل خاطئ».","19:8":"فوقف زكا وقال للرب: «ها أنا يا رب أعطي نصف أموالي للمساكين, وإن كنت قد وشيت بأحد أرد أربعة أضعاف».","19:9":"فقال له يسوع: «اليوم حصل خلاص لهذا البيت, إذ هو أيضا ابن إبراهيم","19:10":"لأن ابن الإنسان قد جاء لكي يطلب ويخلص ما قد هلك».","19:11":"وإذ كانوا يسمعون هذا عاد فقال مثلا, لأنه كان قريبا من أورشليم, وكانوا يظنون أن ملكوت الله عتيد أن يظهر في الحال.","19:12":"فقال: «إنسان شريف الجنس ذهب إلى كورة بعيدة ليأخذ لنفسه ملكا ويرجع.","19:13":"فدعا عشرة عبيد له وأعطاهم عشرة أمناء, وقال لهم: تاجروا حتى آتي.","19:14":"وأما أهل مدينته فكانوا يبغضونه, فأرسلوا وراءه سفارة قائلين: لا نريد أن هذا يملك علينا.","19:15":"ولما رجع بعدما أخذ الملك, أمر أن يدعى إليه أولئك العبيد الذين أعطاهم الفضة, ليعرف بما تاجر كل واحد.","19:16":"فجاء الأول قائلا: يا سيد, مناك ربح عشرة أمناء.","19:17":"فقال له: نعما أيها العبد الصالح لأنك كنت أمينا في القليل, فليكن لك سلطان على عشر مدن.","19:18":"ثم جاء الثاني قائلا: يا سيد, مناك عمل خمسة أمناء.","19:19":"فقال لهذا أيضا: وكن أنت على خمس مدن.","19:20":"ثم جاء آخر قائلا: يا سيد, هوذا مناك الذي كان عندي موضوعا في منديل","19:21":"لأني كنت أخاف منك, إذ أنت إنسان صارم, تأخذ ما لم تضع وتحصد ما لم تزرع.","19:22":"فقال له: من فمك أدينك أيها العبد الشرير. عرفت أني إنسان صارم, آخذ ما لم أضع, وأحصد ما لم أزرع","19:23":"فلماذا لم تضع فضتي على مائدة الصيارفة, فكنت متى جئت أستوفيها مع ربا؟","19:24":"ثم قال للحاضرين: خذوا منه المنا وأعطوه للذي عنده العشرة الأمناء.","19:25":"فقالوا له: يا سيد, عنده عشرة أمناء.","19:26":"لأني أقول لكم: إن كل من له يعطى, ومن ليس له فالذي عنده يؤخذ منه.","19:27":"أما أعدائي, أولئك الذين لم يريدوا أن أملك عليهم, فأتوا بهم إلى هنا واذبحوهم قدامي».","19:28":"ولما قال هذا تقدم صاعدا إلى أورشليم.","19:29":"وإذ قرب من بيت فاجي وبيت عنيا, عند الجبل الذي يدعى جبل الزيتون, أرسل اثنين من تلاميذه","19:30":"قائلا: «اذهبا إلى القرية التي أمامكما, وحين تدخلانها تجدان جحشا مربوطا لم يجلس عليه أحد من الناس قط. فحلاه وأتيا به.","19:31":"وإن سألكما أحد: لماذا تحلانه؟ فقولا له هكذا: إن الرب محتاج إليه».","19:32":"فمضى المرسلان ووجدا كما قال لهما.","19:33":"وفيما هما يحلان الجحش قال لهما أصحابه: «لماذا تحلان الجحش؟»","19:34":"فقالا: «الرب محتاج إليه».","19:35":"وأتيا به إلى يسوع, وطرحا ثيابهما على الجحش, وأركبا يسوع.","19:36":"وفيما هو سائر فرشوا ثيابهم في الطريق.","19:37":"ولما قرب عند منحدر جبل الزيتون, ابتدأ كل جمهور التلاميذ يفرحون ويسبحون الله بصوت عظيم, لأجل جميع القوات التي نظروا","19:38":"قائلين: «مبارك الملك الآتي باسم الرب! سلام في السماء ومجد في الأعالي!».","19:39":"وأما بعض الفريسيين من الجمع فقالوا له: «يا معلم, انتهر تلاميذك».","19:40":"فأجاب وقال لهم: «أقول لكم: إنه إن سكت هؤلاء فالحجارة تصرخ!».","19:41":"وفيما هو يقترب نظر إلى المدينة وبكى عليها","19:42":"قائلا: «إنك لو علمت أنت أيضا, حتى في يومك هذا, ما هو لسلامك. ولكن الآن قد أخفي عن عينيك.","19:43":"فإنه ستأتي أيام ويحيط بك أعداؤك بمترسة, ويحدقون بك ويحاصرونك من كل جهة","19:44":"ويهدمونك وبنيك فيك, ولا يتركون فيك حجرا على حجر, لأنك لم تعرفي زمان افتقادك».","19:45":"ولما دخل الهيكل ابتدأ يخرج الذين كانوا يبيعون ويشترون فيه","19:46":"قائلا لهم: «مكتوب إن بيتي بيت الصلاة. وأنتم جعلتموه مغارة لصوص».","19:47":"وكان يعلم كل يوم في الهيكل, وكان رؤساء الكهنة والكتبة مع وجوه الشعب يطلبون أن يهلكوه","19:48":"ولم يجدوا ما يفعلون, لأن الشعب كله كان متعلقا به يسمع منه.","20:1":"وفي أحد تلك الأيام إذ كان يعلم الشعب في الهيكل ويبشر, وقف رؤساء الكهنة والكتبة مع الشيوخ","20:2":"وكلموه قائلين: «قل لنا بأي سلطان تفعل هذا أو من هو الذي أعطاك هذا السلطان؟»","20:3":"فأجاب وقال لهم: «وأنا أيضا أسألكم كلمة واحدة, فقولوا لي:","20:4":"معمودية يوحنا من السماء كانت أم من الناس؟»","20:5":"فتآمروا فيما بينهم قائلين: «إن قلنا من السماء, يقول: فلماذا لم تؤمنوا به؟","20:6":"وإن قلنا: من الناس, فجميع الشعب يرجموننا, لأنهم واثقون بأن يوحنا نبي».","20:7":"فأجابوا أنهم لا يعلمون من أين.","20:8":"فقال لهم يسوع: «ولا أنا أقول لكم بأي سلطان أفعل هذا».","20:9":"وابتدأ يقول للشعب هذا المثل: «إنسان غرس كرما وسلمه إلى كرامين وسافر زمانا طويلا.","20:10":"وفي الوقت أرسل إلى الكرامين عبدا لكي يعطوه من ثمر الكرم, فجلده الكرامون, وأرسلوه فارغا.","20:11":"فعاد وأرسل عبدا آخر. فجلدوا ذلك أيضا وأهانوه, وأرسلوه فارغا.","20:12":"ثم عاد فأرسل ثالثا. فجرحوا هذا أيضا وأخرجوه.","20:13":"فقال صاحب الكرم: ماذا أفعل؟ أرسل ابني الحبيب. لعلهم إذا رأوه يهابون!","20:14":"فلما رآه الكرامون تآمروا فيما بينهم قائلين: هذا هو الوارث. هلموا نقتله لكي يصير لنا الميراث.","20:15":"فأخرجوه خارج الكرم وقتلوه. فماذا يفعل بهم صاحب الكرم؟","20:16":"يأتي ويهلك هؤلاء الكرامين ويعطي الكرم لآخرين». فلما سمعوا قالوا: «حاشا!»","20:17":"فنظر إليهم وقال: «إذا ما هو هذا المكتوب: الحجر الذي رفضه البناؤون هو قد صار رأس الزاوية.","20:18":"كل من يسقط على ذلك الحجر يترضض, ومن سقط هو عليه يسحقه؟»","20:19":"فطلب رؤساء الكهنة والكتبة أن يلقوا الأيادي عليه في تلك الساعة, ولكنهم خافوا الشعب, لأنهم عرفوا أنه قال هذا المثل عليهم.","20:20":"فراقبوه وأرسلوا جواسيس يتراءون أنهم أبرار لكي يمسكوه بكلمة, حتى يسلموه إلى حكم الوالي وسلطانه.","20:21":"فسألوه قائلين: «يا معلم نعلم أنك بالاستقامة تتكلم وتعلم, ولا تقبل الوجوه, بل بالحق تعلم طريق الله.","20:22":"أيجوز لنا أن نعطي جزية لقيصر أم لا؟»","20:23":"فشعر بمكرهم وقال لهم: «لماذا تجربونني؟","20:24":"أروني دينارا. لمن الصورة والكتابة؟» فأجابوا وقالوا: «لقيصر».","20:25":"فقال لهم: «أعطوا إذا ما لقيصر لقيصر وما لله لله».","20:26":"فلم يقدروا أن يمسكوه بكلمة قدام الشعب, وتعجبوا من جوابه وسكتوا.","20:27":"وحضر قوم من الصدوقيين, الذين يقاومون أمر القيامة, وسألوه:","20:28":"قائلين: «يا معلم كتب لنا موسى: إن مات لأحد أخ وله امرأة, ومات بغير ولد, يأخذ أخوه المرأة ويقيم نسلا لأخيه.","20:29":"فكان سبعة إخوة. وأخذ الأول امرأة ومات بغير ولد","20:30":"فأخذ الثاني المرأة ومات بغير ولد","20:31":"ثم أخذها الثالث, وهكذا السبعة. ولم يتركوا ولدا وماتوا.","20:32":"وآخر الكل ماتت المرأة أيضا.","20:33":"ففي القيامة, لمن منهم تكون زوجة؟ لأنها كانت زوجة للسبعة!»","20:34":"فأجاب وقال لهم يسوع: «أبناء هذا الدهر يزوجون ويزوجون","20:35":"ولكن الذين حسبوا أهلا للحصول على ذلك الدهر والقيامة من الأموات, لا يزوجون ولا يزوجون","20:36":"إذ لا يستطيعون أن يموتوا أيضا, لأنهم مثل الملائكة, وهم أبناء الله, إذ هم أبناء القيامة.","20:37":"وأما أن الموتى يقومون, فقد دل عليه موسى أيضا في أمر العليقة كما يقول: الرب إله إبراهيم وإله إسحاق وإله يعقوب.","20:38":"وليس هو إله أموات بل إله أحياء, لأن الجميع عنده أحياء».","20:39":"فأجاب قوم من الكتبة وقالوا: «يا معلم, حسنا قلت!».","20:40":"ولم يتجاسروا أيضا أن يسألوه عن شيء.","20:41":"وقال لهم: «كيف يقولون إن المسيح ابن داود","20:42":"وداود نفسه يقول في كتاب المزامير: قال الرب لربي: اجلس عن يميني","20:43":"حتى أضع أعداءك موطئا لقدميك.","20:44":"فإذا داود يدعوه ربا. فكيف يكون ابنه؟».","20:45":"وفيما كان جميع الشعب يسمعون قال لتلاميذه:","20:46":"«احذروا من الكتبة الذين يرغبون المشي بالطيالسة, ويحبون التحيات في الأسواق, والمجالس الأولى في المجامع, والمتكآت الأولى في الولائم.","20:47":"الذين يأكلون بيوت الأرامل, ولعلة يطيلون الصلوات. هؤلاء يأخذون دينونة أعظم!».","21:1":"وتطلع فرأى الأغنياء يلقون قرابينهم في الخزانة","21:2":"ورأى أيضا أرملة مسكينة ألقت هناك فلسين.","21:3":"فقال: «بالحق أقول لكم إن هذه الأرملة الفقيرة ألقت أكثر من الجميع","21:4":"لأن هؤلاء من فضلتهم ألقوا في قرابين الله, وأما هذه فمن إعوازها, ألقت كل المعيشة التي لها».","21:5":"وإذ كان قوم يقولون عن الهيكل إنه مزين بحجارة حسنة وتحف, قال:","21:6":"«هذه التي ترونها, ستأتي أيام لا يترك فيها حجر على حجر لا ينقض».","21:7":"فسألوه قائلين: «يا معلم متى يكون هذا وما هي العلامة عندما يصير هذا؟»","21:8":"فقال: «انظروا! لا تضلوا. فإن كثيرين سيأتون باسمي قائلين: إني أنا هو والزمان قد قرب. فلا تذهبوا وراءهم.","21:9":"فإذا سمعتم بحروب وقلاقل فلا تجزعوا, لأنه لا بد أن يكون هذا أولا, ولكن لا يكون المنتهى سريعا».","21:10":"ثم قال لهم: «تقوم أمة على أمة ومملكة على مملكة","21:11":"وتكون زلازل عظيمة في أماكن, ومجاعات وأوبئة. وتكون مخاوف وعلامات عظيمة من السماء.","21:12":"وقبل هذا كله يلقون أيديهم عليكم ويطردونكم, ويسلمونكم إلى مجامع وسجون, وتساقون أمام ملوك وولاة لأجل اسمي.","21:13":"فيؤول ذلك لكم شهادة.","21:14":"فضعوا في قلوبكم أن لا تهتموا من قبل لكي تحتجوا","21:15":"لأني أنا أعطيكم فما وحكمة لا يقدر جميع معانديكم أن يقاوموها أو يناقضوها.","21:16":"وسوف تسلمون من الوالدين والإخوة والأقرباء والأصدقاء, ويقتلون منكم.","21:17":"وتكونون مبغضين من الجميع من أجل اسمي.","21:18":"ولكن شعرة من رؤوسكم لا تهلك.","21:19":"بصبركم اقتنوا أنفسكم.","21:20":"ومتى رأيتم أورشليم محاطة بجيوش, فحينئذ اعلموا أنه قد اقترب خرابها.","21:21":"حينئذ ليهرب الذين في اليهودية إلى الجبال, والذين في وسطها فليفروا خارجا, والذين في الكور فلا يدخلوها","21:22":"لأن هذه أيام انتقام, ليتم كل ما هو مكتوب.","21:23":"وويل للحبالى والمرضعات في تلك الأيام لأنه يكون ضيق عظيم على الأرض وسخط على هذا الشعب.","21:24":"ويقعون بفم السيف, ويسبون إلى جميع الأمم, وتكون أورشليم مدوسة من الأمم, حتى تكمل أزمنة الأمم.","21:25":"«وتكون علامات في الشمس والقمر والنجوم, وعلى الأرض كرب أمم بحيرة. البحر والأمواج تضج","21:26":"والناس يغشى عليهم من خوف وانتظار ما يأتي على المسكونة, لأن قوات السماوات تتزعزع.","21:27":"وحينئذ يبصرون ابن الإنسان آتيا في سحابة بقوة ومجد كثير.","21:28":"ومتى ابتدأت هذه تكون, فانتصبوا وارفعوا رؤوسكم لأن نجاتكم تقترب».","21:29":"وقال لهم مثلا: «انظروا إلى شجرة التين وكل الأشجار.","21:30":"متى أفرخت تنظرون وتعلمون من أنفسكم أن الصيف قد قرب.","21:31":"هكذا أنتم أيضا, متى رأيتم هذه الأشياء صائرة, فاعلموا أن ملكوت الله قريب.","21:32":"الحق أقول لكم: إنه لا يمضي هذا الجيل حتى يكون الكل.","21:33":"السماء والأرض تزولان ولكن كلامي لا يزول.","21:34":"فاحترزوا لأنفسكم لئلا تثقل قلوبكم في خمار وسكر وهموم الحياة, فيصادفكم ذلك اليوم بغتة.","21:35":"لأنه كالفخ يأتي على جميع الجالسين على وجه كل الأرض.","21:36":"اسهروا إذا وتضرعوا في كل حين, لكي تحسبوا أهلا للنجاة من جميع هذا المزمع أن يكون, وتقفوا قدام ابن الإنسان».","21:37":"وكان في النهار يعلم في الهيكل, وفي الليل يخرج ويبيت في الجبل الذي يدعى جبل الزيتون.","21:38":"وكان كل الشعب يبكرون إليه في الهيكل ليسمعوه.","22:1":"وقرب عيد الفطير, الذي يقال له الفصح.","22:2":"وكان رؤساء الكهنة والكتبة يطلبون كيف يقتلونه, لأنهم خافوا الشعب.","22:3":"فدخل الشيطان في يهوذا الذي يدعى الإسخريوطي, وهو من جملة الاثني عشر.","22:4":"فمضى وتكلم مع رؤساء الكهنة وقواد الجند كيف يسلمه إليهم.","22:5":"ففرحوا وعاهدوه أن يعطوه فضة.","22:6":"فواعدهم. وكان يطلب فرصة ليسلمه إليهم خلوا من جمع.","22:7":"وجاء يوم الفطير الذي كان ينبغي أن يذبح فيه الفصح.","22:8":"فأرسل بطرس ويوحنا قائلا: «اذهبا وأعدا لنا الفصح لنأكل».","22:9":"فقالا له: «أين تريد أن نعد؟».","22:10":"فقال لهما: «إذا دخلتما المدينة يستقبلكما إنسان حامل جرة ماء. اتبعاه إلى البيت حيث يدخل","22:11":"وقولا لرب البيت: يقول لك المعلم: أين المنزل حيث آكل الفصح مع تلاميذي؟","22:12":"فذاك يريكما علية كبيرة مفروشة. هناك أعدا».","22:13":"فانطلقا ووجدا كما قال لهما, فأعدا الفصح.","22:14":"ولما كانت الساعة اتكأ والاثنا عشر رسولا معه","22:15":"وقال لهم: «شهوة اشتهيت أن آكل هذا الفصح معكم قبل أن أتألم","22:16":"لأني أقول لكم: إني لا آكل منه بعد حتى يكمل في ملكوت الله».","22:17":"ثم تناول كأسا وشكر وقال: «خذوا هذه واقتسموها بينكم","22:18":"لأني أقول لكم: إني لا أشرب من نتاج الكرمة حتى يأتي ملكوت الله».","22:19":"وأخذ خبزا وشكر وكسر وأعطاهم قائلا: «هذا هو جسدي الذي يبذل عنكم. اصنعوا هذا لذكري».","22:20":"وكذلك الكأس أيضا بعد العشاء قائلا: «هذه الكأس هي العهد الجديد بدمي الذي يسفك عنكم.","22:21":"ولكن هوذا يد الذي يسلمني هي معي على المائدة.","22:22":"وابن الإنسان ماض كما هو محتوم, ولكن ويل لذلك الإنسان الذي يسلمه».","22:23":"فابتدأوا يتساءلون فيما بينهم: «من ترى منهم هو المزمع أن يفعل هذا؟».","22:24":"وكانت بينهم أيضا مشاجرة من منهم يظن أنه يكون أكبر.","22:25":"فقال لهم: «ملوك الأمم يسودونهم, والمتسلطون عليهم يدعون محسنين.","22:26":"وأما أنتم فليس هكذا, بل الكبير فيكم ليكن كالأصغر, والمتقدم كالخادم.","22:27":"لأن من هو أكبر؟ ألذي يتكئ أم الذي يخدم؟ أليس الذي يتكئ؟ ولكني أنا بينكم كالذي يخدم.","22:28":"أنتم الذين ثبتوا معي في تجاربي","22:29":"وأنا أجعل لكم كما جعل لي أبي ملكوتا","22:30":"لتأكلوا وتشربوا على مائدتي في ملكوتي, وتجلسوا على كراسي تدينون أسباط إسرائيل الاثني عشر».","22:31":"وقال الرب: «سمعان, سمعان, هوذا الشيطان طلبكم لكي يغربلكم كالحنطة!","22:32":"ولكني طلبت من أجلك لكي لا يفنى إيمانك. وأنت متى رجعت ثبت إخوتك».","22:33":"فقال له: «يا رب إني مستعد أن أمضي معك حتى إلى السجن وإلى الموت».","22:34":"فقال: «أقول لك يا بطرس لا يصيح الديك اليوم قبل أن تنكر ثلاث مرات أنك تعرفني».","22:35":"ثم قال لهم: «حين أرسلتكم بلا كيس ولا مزود ولا أحذية, هل أعوزكم شيء؟» فقالوا: «لا».","22:36":"فقال لهم: «لكن الآن, من له كيس فليأخذه ومزود كذلك. ومن ليس له فليبع ثوبه ويشتر سيفا.","22:37":"لأني أقول لكم إنه ينبغي أن يتم في أيضا هذا المكتوب: وأحصي مع أثمة. لأن ما هو من جهتي له انقضاء».","22:38":"فقالوا: «يا رب هوذا هنا سيفان». فقال لهم: «يكفي!».","22:39":"وخرج ومضى كالعادة إلى جبل الزيتون, وتبعه أيضا تلاميذه.","22:40":"ولما صار إلى المكان قال لهم: «صلوا لكي لا تدخلوا في تجربة».","22:41":"وانفصل عنهم نحو رمية حجر وجثا على ركبتيه وصلى","22:42":"قائلا: «يا أبتاه, إن شئت أن تجيز عني هذه الكأس. ولكن لتكن لا إرادتي بل إرادتك».","22:43":"وظهر له ملاك من السماء يقويه.","22:44":"وإذ كان في جهاد كان يصلي بأشد لجاجة, وصار عرقه كقطرات دم نازلة على الأرض.","22:45":"ثم قام من الصلاة وجاء إلى تلاميذه, فوجدهم نياما من الحزن.","22:46":"فقال لهم: «لماذا أنتم نيام؟ قوموا وصلوا لئلا تدخلوا في تجربة».","22:47":"وبينما هو يتكلم إذا جمع, والذي يدعى يهوذا, - أحد الاثني عشر, - يتقدمهم, فدنا من يسوع ليقبله.","22:48":"فقال له يسوع: «يا يهوذا, أبقبلة تسلم ابن الإنسان؟»","22:49":"فلما رأى الذين حوله ما يكون قالوا: «يا رب أنضرب بالسيف؟»","22:50":"وضرب واحد منهم عبد رئيس الكهنة فقطع أذنه اليمنى.","22:51":"فأجاب يسوع وقال: «دعوا إلى هذا!» ولمس أذنه وأبرأها.","22:52":"ثم قال يسوع لرؤساء الكهنة وقواد جند الهيكل والشيوخ المقبلين عليه: «كأنه على لص خرجتم بسيوف وعصي!","22:53":"إذ كنت معكم كل يوم في الهيكل لم تمدوا علي الأيادي. ولكن هذه ساعتكم وسلطان الظلمة».","22:54":"فأخذوه وساقوه وأدخلوه إلى بيت رئيس الكهنة. وأما بطرس فتبعه من بعيد.","22:55":"ولما أضرموا نارا في وسط الدار وجلسوا معا, جلس بطرس بينهم.","22:56":"فرأته جارية جالسا عند النار فتفرست فيه وقالت: «وهذا كان معه».","22:57":"فأنكره قائلا: «لست أعرفه يا امرأة!»","22:58":"وبعد قليل رآه آخر وقال: «وأنت منهم!» فقال بطرس: «يا إنسان, لست أنا!»","22:59":"ولما مضى نحو ساعة واحدة أكد آخر قائلا: «بالحق إن هذا أيضا كان معه, لأنه جليلي أيضا».","22:60":"فقال بطرس: «يا إنسان, لست أعرف ما تقول». وفي الحال بينما هو يتكلم صاح الديك.","22:61":"فالتفت الرب ونظر إلى بطرس, فتذكر بطرس كلام الرب, كيف قال له: «إنك قبل أن يصيح الديك تنكرني ثلاث مرات».","22:62":"فخرج بطرس إلى خارج وبكى بكاء مرا.","22:63":"والرجال الذين كانوا ضابطين يسوع كانوا يستهزئون به وهم يجلدونه","22:64":"وغطوه وكانوا يضربون وجهه ويسألونه قائلين: «تنبأ! من هو الذي ضربك؟»","22:65":"وأشياء أخر كثيرة كانوا يقولون عليه مجدفين.","22:66":"ولما كان النهار اجتمعت مشيخة الشعب: رؤساء الكهنة والكتبة, وأصعدوه إلى مجمعهم","22:67":"قائلين: «إن كنت أنت المسيح, فقل لنا». فقال لهم: «إن قلت لكم لا تصدقون","22:68":"وإن سألت لا تجيبونني ولا تطلقونني.","22:69":"منذ الآن يكون ابن الإنسان جالسا عن يمين قوة الله».","22:70":"فقال الجميع: «أفأنت ابن الله؟» فقال لهم: «أنتم تقولون إني أنا هو».","22:71":"فقالوا: «ما حاجتنا بعد إلى شهادة؟ لأننا نحن سمعنا من فمه».","23:1":"فقام كل جمهورهم وجاءوا به إلى بيلاطس","23:2":"وابتدأوا يشتكون عليه قائلين: «إننا وجدنا هذا يفسد الأمة, ويمنع أن تعطى جزية لقيصر, قائلا: إنه هو مسيح ملك».","23:3":"فسأله بيلاطس قائلا: «أنت ملك اليهود؟» فأجابه وقال: «أنت تقول».","23:4":"فقال بيلاطس لرؤساء الكهنة والجموع: «إني لا أجد علة في هذا الإنسان».","23:5":"فكانوا يشددون قائلين: «إنه يهيج الشعب وهو يعلم في كل اليهودية مبتدئا من الجليل إلى هنا».","23:6":"فلما سمع بيلاطس ذكر الجليل, سأل: «هل الرجل جليلي؟»","23:7":"وحين علم أنه من سلطنة هيرودس, أرسله إلى هيرودس, إذ كان هو أيضا تلك الأيام في أورشليم.","23:8":"وأما هيرودس فلما رأى يسوع فرح جدا, لأنه كان يريد من زمان طويل أن يراه, لسماعه عنه أشياء كثيرة, وترجى أن يرى آية تصنع منه.","23:9":"وسأله بكلام كثير فلم يجبه بشيء.","23:10":"ووقف رؤساء الكهنة والكتبة يشتكون عليه باشتداد","23:11":"فاحتقره هيرودس مع عسكره واستهزأ به, وألبسه لباسا لامعا, ورده إلى بيلاطس.","23:12":"فصار بيلاطس وهيرودس صديقين مع بعضهما في ذلك اليوم, لأنهما كانا من قبل في عداوة بينهما.","23:13":"فدعا بيلاطس رؤساء الكهنة والعظماء والشعب","23:14":"وقال لهم: «قد قدمتم إلي هذا الإنسان كمن يفسد الشعب. وها أنا قد فحصت قدامكم ولم أجد في هذا الإنسان علة مما تشتكون به عليه.","23:15":"ولا هيرودس أيضا, لأني أرسلتكم إليه. وها لا شيء يستحق الموت صنع منه.","23:16":"فأنا أؤدبه وأطلقه».","23:17":"وكان مضطرا أن يطلق لهم كل عيد واحدا","23:18":"فصرخوا بجملتهم قائلين: «خذ هذا وأطلق لنا باراباس!»","23:19":"وذاك كان قد طرح في السجن لأجل فتنة حدثت في المدينة وقتل.","23:20":"فناداهم أيضا بيلاطس وهو يريد أن يطلق يسوع","23:21":"فصرخوا قائلين: «اصلبه! اصلبه!»","23:22":"فقال لهم ثالثة: «فأي شر عمل هذا؟ إني لم أجد فيه علة للموت, فأنا أؤدبه وأطلقه».","23:23":"فكانوا يلجون بأصوات عظيمة طالبين أن يصلب. فقويت أصواتهم وأصوات رؤساء الكهنة.","23:24":"فحكم بيلاطس أن تكون طلبتهم.","23:25":"فأطلق لهم الذي طرح في السجن لأجل فتنة وقتل, الذي طلبوه, وأسلم يسوع لمشيئتهم.","23:26":"ولما مضوا به أمسكوا سمعان, رجلا قيروانيا كان آتيا من الحقل, ووضعوا عليه الصليب ليحمله خلف يسوع.","23:27":"وتبعه جمهور كثير من الشعب, والنساء اللواتي كن يلطمن أيضا وينحن عليه.","23:28":"فالتفت إليهن يسوع وقال: «يا بنات أورشليم, لا تبكين علي بل ابكين على أنفسكن وعلى أولادكن","23:29":"لأنه هوذا أيام تأتي يقولون فيها: طوبى للعواقر والبطون التي لم تلد والثدي التي لم ترضع.","23:30":"حينئذ يبتدئون يقولون للجبال: اسقطي علينا وللآكام: غطينا.","23:31":"لأنه إن كانوا بالعود الرطب يفعلون هذا, فماذا يكون باليابس؟».","23:32":"وجاءوا أيضا باثنين آخرين مذنبين ليقتلا معه.","23:33":"ولما مضوا به إلى الموضع الذي يدعى «جمجمة» صلبوه هناك مع المذنبين, واحدا عن يمينه والآخر عن يساره.","23:34":"فقال يسوع: «يا أبتاه اغفر لهم, لأنهم لا يعلمون ماذا يفعلون». وإذ اقتسموا ثيابه اقترعوا عليها.","23:35":"وكان الشعب واقفين ينظرون, والرؤساء أيضا معهم يسخرون به قائلين: «خلص آخرين, فليخلص نفسه إن كان هو المسيح مختار الله».","23:36":"والجند أيضا استهزأوا به وهم يأتون ويقدمون له خلا","23:37":"قائلين: «إن كنت أنت ملك اليهود فخلص نفسك».","23:38":"وكان عنوان مكتوب فوقه بأحرف يونانية ورومانية وعبرانية: «هذا هو ملك اليهود».","23:39":"وكان واحد من المذنبين المعلقين يجدف عليه قائلا: «إن كنت أنت المسيح, فخلص نفسك وإيانا!»","23:40":"فأجاب الآخر وانتهره قائلا: «أولا أنت تخاف الله, إذ أنت تحت هذا الحكم بعينه؟","23:41":"أما نحن فبعدل, لأننا ننال استحقاق ما فعلنا, وأما هذا فلم يفعل شيئا ليس في محله».","23:42":"ثم قال ليسوع: «اذكرني يا رب متى جئت في ملكوتك».","23:43":"فقال له يسوع: «الحق أقول لك: إنك اليوم تكون معي في الفردوس».","23:44":"وكان نحو الساعة السادسة, فكانت ظلمة على الأرض كلها إلى الساعة التاسعة.","23:45":"وأظلمت الشمس, وانشق حجاب الهيكل من وسطه.","23:46":"ونادى يسوع بصوت عظيم وقال: «يا أبتاه, في يديك أستودع روحي». ولما قال هذا أسلم الروح.","23:47":"فلما رأى قائد المئة ما كان, مجد الله قائلا: «بالحقيقة كان هذا الإنسان بارا!»","23:48":"وكل الجموع الذين كانوا مجتمعين لهذا المنظر, لما أبصروا ما كان, رجعوا وهم يقرعون صدورهم.","23:49":"وكان جميع معارفه, ونساء كن قد تبعنه من الجليل, واقفين من بعيد ينظرون ذلك.","23:50":"وإذا رجل اسمه يوسف, وكان مشيرا ورجلا صالحا بارا -","23:51":"هذا لم يكن موافقا لرأيهم وعملهم, وهو من الرامة مدينة لليهود. وكان هو أيضا ينتظر ملكوت الله.","23:52":"هذا تقدم إلى بيلاطس وطلب جسد يسوع","23:53":"وأنزله, ولفه بكتان, ووضعه في قبر منحوت حيث لم يكن أحد وضع قط.","23:54":"وكان يوم الاستعداد والسبت يلوح.","23:55":"وتبعته نساء كن قد أتين معه من الجليل, ونظرن القبر وكيف وضع جسده.","23:56":"فرجعن وأعددن حنوطا وأطيابا. وفي السبت استرحن حسب الوصية.","24:1":"ثم في أول الأسبوع, أول الفجر, أتين إلى القبر حاملات الحنوط الذي أعددنه, ومعهن أناس.","24:2":"فوجدن الحجر مدحرجا عن القبر","24:3":"فدخلن ولم يجدن جسد الرب يسوع.","24:4":"وفيما هن محتارات في ذلك, إذا رجلان وقفا بهن بثياب براقة.","24:5":"وإذ كن خائفات ومنكسات وجوههن إلى الأرض, قالا لهن: «لماذا تطلبن الحي بين الأموات؟","24:6":"ليس هو ههنا, لكنه قام! اذكرن كيف كلمكن وهو بعد في الجليل","24:7":"قائلا: إنه ينبغي أن يسلم ابن الإنسان في أيدي أناس خطاة, ويصلب, وفي اليوم الثالث يقوم».","24:8":"فتذكرن كلامه","24:9":"ورجعن من القبر, وأخبرن الأحد عشر وجميع الباقين بهذا كله.","24:10":"وكانت مريم المجدلية ويونا ومريم أم يعقوب والباقيات معهن, اللواتي قلن هذا للرسل.","24:11":"فتراءى كلامهن لهم كالهذيان ولم يصدقوهن.","24:12":"فقام بطرس وركض إلى القبر, فانحنى ونظر الأكفان موضوعة وحدها, فمضى متعجبا في نفسه مما كان.","24:13":"وإذا اثنان منهم كانا منطلقين في ذلك اليوم إلى قرية بعيدة عن أورشليم ستين غلوة, اسمها «عمواس».","24:14":"وكانا يتكلمان بعضهما مع بعض عن جميع هذه الحوادث.","24:15":"وفيما هما يتكلمان ويتحاوران, اقترب إليهما يسوع نفسه وكان يمشي معهما.","24:16":"ولكن أمسكت أعينهما عن معرفته.","24:17":"فقال لهما: «ما هذا الكلام الذي تتطارحان به وأنتما ماشيان عابسين؟»","24:18":"فأجاب أحدهما, الذي اسمه كليوباس وقال له: «هل أنت متغرب وحدك في أورشليم ولم تعلم الأمور التي حدثت فيها في هذه الأيام؟»","24:19":"فقال لهما: «وما هي؟» فقالا: «المختصة بيسوع الناصري, الذي كان إنسانا نبيا مقتدرا في الفعل والقول أمام الله وجميع الشعب.","24:20":"كيف أسلمه رؤساء الكهنة وحكامنا لقضاء الموت وصلبوه.","24:21":"ونحن كنا نرجو أنه هو المزمع أن يفدي إسرائيل. ولكن, مع هذا كله, اليوم له ثلاثة أيام منذ حدث ذلك.","24:22":"بل بعض النساء منا حيرننا إذ كن باكرا عند القبر","24:23":"ولما لم يجدن جسده أتين قائلات: إنهن رأين منظر ملائكة قالوا إنه حي.","24:24":"ومضى قوم من الذين معنا إلى القبر, فوجدوا هكذا كما قالت أيضا النساء, وأما هو فلم يروه».","24:25":"فقال لهما: «أيها الغبيان والبطيئا القلوب في الإيمان بجميع ما تكلم به الأنبياء","24:26":"أما كان ينبغي أن المسيح يتألم بهذا ويدخل إلى مجده؟»","24:27":"ثم ابتدأ من موسى ومن جميع الأنبياء يفسر لهما الأمور المختصة به في جميع الكتب.","24:28":"ثم اقتربوا إلى القرية التي كانا منطلقين إليها, وهو تظاهر كأنه منطلق إلى مكان أبعد.","24:29":"فألزماه قائلين: «امكث معنا, لأنه نحو المساء وقد مال النهار». فدخل ليمكث معهما.","24:30":"فلما اتكأ معهما, أخذ خبزا وبارك وكسر وناولهما","24:31":"فانفتحت أعينهما وعرفاه ثم اختفى عنهما","24:32":"فقال بعضهما لبعض: «ألم يكن قلبنا ملتهبا فينا إذ كان يكلمنا في الطريق ويوضح لنا الكتب؟»","24:33":"فقاما في تلك الساعة ورجعا إلى أورشليم, ووجدا الأحد عشر مجتمعين, هم والذين معهم","24:34":"وهم يقولون: «إن الرب قام بالحقيقة وظهر لسمعان!»","24:35":"وأما هما فكانا يخبران بما حدث في الطريق, وكيف عرفاه عند كسر الخبز.","24:36":"وفيما هم يتكلمون بهذا وقف يسوع نفسه في وسطهم, وقال لهم: «سلام لكم!»","24:37":"فجزعوا وخافوا, وظنوا أنهم نظروا روحا.","24:38":"فقال لهم: «ما بالكم مضطربين, ولماذا تخطر أفكار في قلوبكم؟","24:39":"انظروا يدي ورجلي: إني أنا هو. جسوني وانظروا, فإن الروح ليس له لحم وعظام كما ترون لي».","24:40":"وحين قال هذا أراهم يديه ورجليه.","24:41":"وبينما هم غير مصدقين من الفرح, ومتعجبون, قال لهم: «أعندكم ههنا طعام؟»","24:42":"فناولوه جزءا من سمك مشوي, وشيئا من شهد عسل.","24:43":"فأخذ وأكل قدامهم.","24:44":"وقال لهم: «هذا هو الكلام الذي كلمتكم به وأنا بعد معكم أنه لا بد أن يتم جميع ما هو مكتوب عني في ناموس موسى والأنبياء والمزامير».","24:45":"حينئذ فتح ذهنهم ليفهموا الكتب.","24:46":"وقال لهم: «هكذا هو مكتوب, وهكذا كان ينبغي أن المسيح يتألم ويقوم من الأموات في اليوم الثالث","24:47":"وأن يكرز باسمه بالتوبة ومغفرة الخطايا لجميع الأمم, مبتدأ من أورشليم.","24:48":"وأنتم شهود لذلك.","24:49":"وها أنا أرسل إليكم موعد أبي. فأقيموا في مدينة أورشليم إلى أن تلبسوا قوة من الأعالي».","24:50":"وأخرجهم خارجا إلى بيت عنيا, ورفع يديه وباركهم.","24:51":"وفيما هو يباركهم, انفرد عنهم وأصعد إلى السماء.","24:52":"فسجدوا له ورجعوا إلى أورشليم بفرح عظيم","24:53":"وكانوا كل حين في الهيكل يسبحون ويباركون الله. آمين."};
